window.AUTH=window.AUTH||{};window.AUTH["23-1187"]={"d":"23-1187","id":"2024/23-1187","n":"Food and Drug Administration v. R.J. Reynolds Vapor Co.","briefs":[{"k":"petitioner","label":"Brief of petitioners Food and Drug Administration, et al.","date":"2024-11-13","url":"https://www.supremecourt.gov/DocketPDF/23/23-1187/331765/20241113172919870_23-1187ts.pdf","side":"pet","n":124},{"k":"respondent","label":"Brief of respondents R.J. Reynolds Vapor Co., et al.","date":"2024-12-16","url":"https://www.supremecourt.gov/DocketPDF/23/23-1187/335477/20241218121727006_Menthol%20Alto%20Merits%20Response%20Brief.pdf","side":"res","n":119},{"k":"reply","label":"Reply of petitioners Food and Drug Administration, et al.","date":"2025-01-10","url":"https://www.supremecourt.gov/DocketPDF/23/23-1187/336987/20250110123741661_23-1187reply.pdf","side":"pet","n":81}],"opinion":"https://www.supremecourt.gov/opinions/24pdf/606us1r57_n6io.pdf","tr":true,"items":[{"t":"case","label":"Air Courier Conference of America v. American Postal Workers Union","cite":"498 U.S. 517","y":1991,"id":"1990/89-1416","sc":1,"op":1,"sum":"The United States Postal Service's monopoly over the carriage of letters in and from the Nation is codified in a group of statutes known as the Private Express Statutes (PES). The monopoly was created by Congress as a revenue protection measure for the Postal Service vis-A-vis private competitors. Pursuant to a PES provision allowing it to suspend PES restrictions as to any mail route where the public interest so …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13","1":"30, 31, 32"}},{"t":"case","label":"Alabama v. North Carolina","cite":"560 U.S. 330","y":2010,"id":"2009/132-orig","sc":1,"sum":"The Court held that Alabama did not have the power to impose monetary sanctions against North Carolina for violating a multi-state waste cleanup compact.","sumSrc":"Oyez","by":{"0":"30","1":"43"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"case","label":"Amerada Petroleum Corp. v. Federal Power Commission","cite":"338 F.2d 808","y":1964,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/338/808/","sum":"Interpreting a similarly worded venue statute to mean that an outof-circuit petitioner could not join a local petitioner.","sumSrc":"brief:0","by":{"0":"26","1":"48","2":"18, 19"}},{"t":"case","label":"Atlantic Marine Construction Co. v. United States District Court","cite":"571 U.S. 49","y":2013,"id":"2013/12-929","sc":1,"op":1,"sum":"The Court held that the Federal Rules of Procedure allow two opposing parties in a lawsuit to transfer the litigation to a more convenient forum rather than being dismissed entirely.","sumSrc":"Oyez","by":{"0":"34","1":"50","2":"21"}},{"t":"case","label":"Avail Vapor, LLC v. FDA","cite":"55 F.4th 409","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/55/409/","op":7,"ar":2,"by":{"0":"3, 5"}},{"t":"case","label":"Bankers Life & Casualty Co. v. Holland","cite":"346 U.S. 379","y":1953,"id":"scdb/1953-011","sc":1,"sum":"In the circumstances of this case, mandamus against a federal district judge was not an appropriate remedy to vacate a severance and transfer order entered by him under 28 U. S. C. § 1406 (a) on the ground of improper venue.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 32","1":"47","2":"14, 20"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"op":3,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"0":"12, 13","1":"24, 26, 32, 33","2":"9, 11"}},{"t":"case","label":"Block v. Community Nutrition Institute","cite":"467 U.S. 340","y":1984,"id":"1983/83-458","sc":1,"op":6,"sum":"The individual consumers may not obtain judicial review of the milk market orders in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23-25","1":"24, 34, 35","2":"10"}},{"t":"case","label":"Camp v. Gress","cite":"250 U.S. 308","y":1919,"id":"scdb/1918-082","sc":1,"sum":"Under § 51 of the Judicial Code (Act of 1887-1888, § 1), when an action for damáges is brought against several defendants in the district where some of them reside and the jurisdiction of the District Court is founded solely on diversity of citizenship, a codefendant cannot be compelled to submit to the jurisdiction by service in that district if he is a citizen and resident of another State. P.311. Smithy. Lyon, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31","1":"46"}},{"t":"case","label":"Center for Reproductive Law & Policy v. Bush","cite":"304 F.3d 183","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/304/183/","by":{"0":"15"}},{"t":"case","label":"Chicago, Rock Island, & Pacific Ry. Co. v. Martin","cite":"178 U.S. 245","y":1900,"id":"scdb/1899-057","sc":1,"sum":"This was an ordinary action, under a state statute, for wrongfully causing the death of plaintiff’s intestate, in which no Federal question was presented by the pleadings, or litigated at the trial, and in which the liability depended upon principles of general law, and not in any way upon the terms of the order appointing the receivers; and whatever the rights of the receivers might have been to remove the cause if …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Citizens Bank of Maryland v. Strumpf","cite":"516 U.S. 16","y":1995,"id":"1995/94-1340","sc":1,"sum":"When respondent filed for relief under the Bankruptcy Code, he had a checking account with, and was in default on the remaining balance of a loan from, petitioner bank. Under the Code, a bankruptcy filing gives rise to an automatic stay of a creditor's \"setoff of any debt owing to the debtor that arose before the commencement of the [bankruptcy case] against any claim against the debtor.\" 11 U. S. C. §362(a)(7). …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35"}},{"t":"case","label":"Clark v. Paul Gray, Inc.","cite":"306 U.S. 583","y":1939,"id":"scdb/1938-097","sc":1,"sum":"1. The Court raises sua sponte the question whether jurisdictional amounts were in controversy in the District Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"47"}},{"t":"case","label":"Community Nutrition Institute v. Block","cite":"698 F.2d 1239","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/698/1239/","by":{"0":"23, 24"}},{"t":"case","label":"Cummings v. Premier Rehab Keller, P.L.L.C.","cite":"596 U.S. 212","y":2022,"id":"2021/20-219","sc":1,"sum":"Emotional distress damages are not recoverable in a private action to enforce either the Rehabilitation Act of 1973 or the Affordable Care Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"Department of State v. Muñoz","cite":"602 U.S. 899","y":2024,"url":"https://supreme.justia.com/cases/federal/us/602/899/","sc":1,"by":{"0":"15","2":"3"}},{"t":"case","label":"Director, Office of Workers’ Compensation Programs v. Newport News Shipbuilding & Dry Dock Co.","cite":"514 U.S. 122","y":1995,"id":"1994/93-1783","sc":1,"op":5,"sum":"The Director is not \"adversely affected or aggrieved\" under §921(c).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 13, 18, 25, 26","1":"19, 26","2":"5, 6"}},{"t":"case","label":"FCC v. Sanders Brothers Radio Station","cite":"309 U.S. 470","y":1940,"id":"scdb/1939-112","sc":1,"op":1,"sum":"Holding that competitors of FCC licensees are “adversely affected” by an order granting a license within the meaning of § 402(b)(2) of the Communications Act of 1934.","sumSrc":"opinion","by":{"0":"15","1":"20"}},{"t":"case","label":"FDA v. Brown & Williamson Tobacco Corp.","cite":"529 U.S. 120","y":2000,"id":"1999/98-1152","sc":1,"sum":"The Court held that \"Congress has not given the FDA the authority to regulate tobacco products as customarily marketed.\" The ruling was based on the FDCA as a whole and in conjunction with Congress' subsequent tobacco-specific legislation. \"By no means do we question the seriousness of the problem that the FDA has sought to address,\" Justice O'Connor wrote for the majority.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Gableman v. Peoria, Decatur, & Evansville Ry. Co.","cite":"179 U.S. 335","y":1900,"id":"scdb/1900-038","sc":1,"sum":"An action against a receiver of a state corporation is not a case arising under the Constitution and laws of the United States simply by reason of the fact that such receiver was appointed by a court of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Geneva Furniture Manufacturing Co. v. S. Karpen & Bros.","cite":"238 U.S. 254","y":1915,"id":"scdb/1914-164","sc":1,"sum":"Where the plaintiff really makes a substantial claim, under an Act of Congress, the District Court has jurisdiction whether the claim ultimately be held good or bad. The Fair v. Kohler Die Co., 222 U. S. 22.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"32","1":"47"}},{"t":"case","label":"Holman v. Johnson","cite":"98 Eng. Rep. 1120","y":1775,"court":"K.B.","url":"https://www.courtlistener.com/c/Eng.%20Rep./98/1120/","by":{"0":"22"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"sum":"The Court held that non-citizens who are subject to mandatory detention under the Immigration and Nationality Act are not entitled to periodic bond hearings. with the possibility of release if they are detained for longer than six months.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Joint Anti-Fascist Refugee Committee v. McGrath","cite":"341 U.S. 123","y":1951,"id":"scdb/1950-068","sc":1,"op":1,"sum":"Recognizing that the likelihood that a person would be “adequately protected” by the party who is able to challenge the underlying Government action is a “relevant consideration” when determining the scope of judicial review.","sumSrc":"opinion","by":{"0":"15, 16"}},{"t":"case","label":"Kloeckner v. Solis","cite":"568 U.S. 41","y":2012,"id":"2012/11-184","sc":1,"sum":"The Court found that the district court, rather than the Court of Appeals, has jurisdiction over \"mixed\" cases that have been dismissed by the Merit Systems Protection Board.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Leroy v. Great Western United Corp.","cite":"443 U.S. 173","y":1979,"id":"1978/78-759","sc":1,"sum":"After publicly announcing its intent to make a tender offer to purchase shares of stock of a company having substantial assets in Idaho, appellee, a Texas-based corporation which is also engaged in business in New York and Maryland, filed the informational schedule with the Securities and Exchange Commission required by the Securities Exchange Act of 1934 (1934 Act), as amended by the Williams Act, and also filed …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33, 34","1":"50"}},{"t":"case","label":"Lexmark International, Inc. v. Static Control Components, Inc.","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"op":13,"ar":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"12, 13, 25","1":"24, 29, 32, 33","2":"5, 6"}},{"t":"case","label":"Life Technologies Corp. v. Promega Corp.","cite":"580 U.S. 140","y":2017,"id":"2016/14-1538","sc":1,"sum":"The Court held that supplying a single component of a multi-component invention from the United States for sale abroad does not expose the manufacturer to liability for infringement based on worldwide sales.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Lujan v. National Wildlife Federation","cite":"497 U.S. 871","y":1990,"id":"1989/89-640","sc":1,"op":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Supreme Court held that NWF did not have standing to challenge the land-use designations. The two timely affidavits were not enough to show that the group members had actually been affected by the BLM decisions.","sumSrc":"Oyez","by":{"0":"12, 13"}},{"t":"case","label":"National Ass’n of Manufacturers v. Department of Defense","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"0":"25","2":"3"}},{"t":"case","label":"National Family Farm Coalition v. EPA","cite":"966 F.3d 893","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/966/893/","op":2,"by":{"0":"27, 29","1":"49","2":"20"}},{"t":"case","label":"Niz-Chavez v. Garland","cite":"593 U.S. 155","y":2021,"id":"2020/19-863","sc":1,"sum":"A notice to appear sufficient to trigger the Illegal Immigration Reform and Immigrant Responsibility Act of 1996’s stop-time rule is a single document containing all the information about an individual’s removal hearing specified in 8 U. S. C. §1229(a)(1).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"28"}},{"t":"case","label":"O’Bannon v. Town Court Nursing Center","cite":"447 U.S. 773","y":1980,"id":"1979/78-1318","sc":1,"sum":"The patients have no interest in receiving benefits for care in a particular facility that entitles them, as a matter of constitutional law, to a hearing before HEW and DPW can decertify that facility. Whatever legal rights the patients may have against the nursing home for failing to maintain its status as a qualified nursing home, the enforcement by HEW and DPW of their valid regulations did not directly affect …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15"}},{"t":"case","label":"Paperworkers v. Misco, Inc.","cite":"484 U.S. 29","y":1987,"id":"1987/86-651","sc":1,"sum":"Respondent employer's collective-bargaining agreement with petitioner union authorizes the submission to binding arbitration of any grievance that arises from the interpretation or application of the agreement's terms, and reserves to management the right to establish, amend, and enforce rules regulating employee discharge and discipline and setting forth disciplinary procedures. One of respondent's rules listed as …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22"}},{"t":"case","label":"Prohibition Juice Co. v. FDA","cite":"45 F.4th 8","y":2022,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/45/8/","op":1,"by":{"0":"5"}},{"t":"case","label":"Pugin v. Garland","cite":"599 U.S. 600","y":2023,"id":"2022/22-23","sc":1,"sum":"An offense may “relate to” obstruction of justice under the Immigration and Nationality Act’s definition of an “aggravated felony,” 8 U. S. C. §1101(a)(43)(S), even if the offense does not require that an investigation or proceeding be pending.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35"}},{"t":"case","label":"Radiofone, Inc. v. FCC","cite":"759 F.2d 936","y":1985,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/759/936/","by":{"0":"14, 15"}},{"t":"case","label":"R.J. Reynolds Vapor Co. v. FDA","cite":"65 F.4th 182","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/65/182/","by":{"0":"5, 6, 26","1":"6, 8"}},{"t":"case","label":"Rockwell International Corp. v. United States","cite":"549 U.S. 457","y":2007,"id":"2006/05-1272","sc":1,"sum":"The Court ruled 6-2 that Stone did not qualify as an \"original source\" with \"direct and independent knowledge of the information on which the allegations are based\" for purposes of the False Claims Act.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"sum":"Instead, in 5-to-4 opinion written by Chief Justice William H. Rehnquist, the Court found that the case had been improperly filed. Under federal law, a petition for a writ of habeas corpus can only be filed against the person directly responsible for a prisoner's confinement or, put another way, the person with the power to bring the prisoner to court.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Shady Grove Orthopedic Assocs., P.A. v. Allstate Insurance Co.","cite":"559 U.S. 393","y":2010,"id":"2009/08-1008","sc":1,"sum":"The Court held that Section 901(b) of the New York Rules of Civil Procedure does not preclude a federal court ruling on entities from different jurisdictions from hearing a class action under Rule 23 of the Federal Rules of Civil Procedure.","sumSrc":"Oyez","by":{"0":"30","1":"43"}},{"t":"case","label":"Shaw v. Quincy Mining Co.","cite":"145 U.S. 444","y":1892,"id":"scdb/1891-247","sc":1,"sum":"Under the act of March 3, 1887, c. 373, § 1, as corrected by the actof August 13, 1888, c. 866, a corporation, incorporated in one State only, cannot be compelled to answer, in a Circuit Court of the United States held in another State, in which it has a usual place of business, to a civil suit, at law or in equity, brought by a citizen of a different State.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"10"}},{"t":"case","label":"Sims v. Apfel","cite":"530 U.S. 103","y":2000,"id":"1999/98-9537","sc":1,"sum":"The Court held, 5 to 4, that Social Security claimants who exhaust administrative remedies need not also exhaust issues administratively in order to preserve judicial review of those issues.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"Smith v. Lyon","cite":"133 U.S. 315","y":1890,"id":"scdb/1889-115","sc":1,"sum":"Under the act of March 3, 1887, 24 Stat. 552, c..373, as amended by the act of August 13, 1888, 25 Stat. 433,86G, a Circuit Court of the United States has not jurisdiction, on the ground of diverse citizenship, if there are two plaintiffs to the action, who are citizens of and residents in different States, and the defendant is a citizen of and resident in a third State, and the action is brought in the State in …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"9, 31","1":"46, 47","2":"17"}},{"t":"case","label":"Sprint Communications Co. v. APCC Services, Inc.","cite":"554 U.S. 269","y":2008,"id":"2007/07-552","sc":1,"sum":"In a close 5-4 ruling, the Court held that third-party companies like APCC have standing to pursue legal claims that have been assigned to them, even when they must then pass along any proceeds from the litigation to the pay-phone operators who hired them.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Strawbridge v. Curtiss","cite":"3 Cranch 267","y":1806,"url":"https://www.courtlistener.com/c/Cranch/3/267/","by":{"0":"32"}},{"t":"case","label":"TC Heartland LLC v. Kraft Foods Group Brands LLC","cite":"581 U.S. 258","y":2017,"id":"2016/16-341","sc":1,"op":1,"sum":"The Court held that the subsection of the general venue statute that allows a corporation to reside in many jurisdictions for the purpose of establishing jurisdiction does not apply to the patent venue statute.","sumSrc":"Oyez","by":{"0":"10","1":"13"}},{"t":"case","label":"Thompson v. North American Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"op":10,"sum":"Observing that “absurd consequences” about who was entitled to sue would follow if the Court were to interpret literally a similarly worded cause of action.","sumSrc":"opinion","by":{"0":"12","1":"19, 20"}},{"t":"case","label":"T-Mobile South, LLC v. City of Roswell","cite":"574 U.S. 293","y":2015,"id":"2014/13-975","sc":1,"sum":"The Court held that the Telecommunications Act of 1996 does not require localities to provide reasons for their denial of construction applications in the written denial notification as long as the reasons appear in some other sufficiently clear written record.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"United States v. Gooding","cite":"12 Wheat. 460","y":1827,"url":"https://www.courtlistener.com/c/Wheat./12/460/","by":{"0":"28"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"21"}},{"t":"case","label":"United States ex rel. Merena v. SmithKline Beecham Corp.","cite":"205 F.3d 97","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/205/97/","by":{"0":"30"}},{"t":"case","label":"Valley Forge Christian College v. Americans United for Separation of Church & State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"sum":"The Court held that Americans United for Separation of Church and State did not have standing to sue. Justice Rehnquist argued that the group did not pass the first prong of the Court's test for taxpayer standing.","sumSrc":"Oyez","by":{"0":"18","2":"5"}},{"t":"case","label":"Wages & White Lion Investments, L.L.C. v. FDA","cite":"41 F.4th 427","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/41/427/","op":1,"by":{"0":"5"}},{"t":"case","label":"Wages & White Lion Investments, L.L.C. v. FDA","cite":"58 F.4th 233","y":2023,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/58/233/","op":1,"by":{"0":"5"}},{"t":"case","label":"Wages & White Lion Investments, L.L.C. v. FDA","cite":"90 F.4th 357","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/90/357/","op":1,"by":{"0":"5"}},{"t":"case","label":"Ysleta del sur Pueblo v. Texas","cite":"596 U.S. 685","y":2022,"id":"2021/20-493","sc":1,"sum":"The federal legislation at issue—the Ysleta del Sur and Alabama and Coushatta Indian Tribes of Texas Restoration Act—bans as a matter of federal law on tribal lands only those gaming activities also banned in Texas.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34"}},{"t":"case","label":"Zahn v. International Paper Co.","cite":"414 U.S. 291","y":1973,"id":"1973/72-888","sc":1,"sum":"Multiple plaintiffs with separate and distinct claims must each satisfy the jurisdictional amount for suits in federal courts, and in this diversity class action under Fed. Rule Civ. Proc. 23 (b) (3) by owners of lakeshore property cfiarging respondent with polluting the lake, where only the named plaintiffs but not the unnamed plaintiffs could show damages in the jurisdictional amount, a class action is not …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","1":"47"}},{"t":"const","label":"Article II","clauses":[["executive-vesting","Executive Vesting Clause"],["natural-born","Natural-Born Citizen Clause"],["commander-in-chief","Commander in Chief Clause"],["pardon","Pardon Clause"],["treaty","Treaty Clause"],["appointments","Appointments Clause"],["take-care","Take Care Clause"],["impeachment","Impeachment"]],"by":{"0":"21"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(6)"],"by":{"0":"3, 14"}},{"t":"usc","label":"5 U.S.C. § 552","url":"https://www.law.cornell.edu/uscode/text/5/552","subs":["(b)(4)"],"by":{"0":"18"}},{"t":"usc","label":"5 U.S.C. § 702","url":"https://www.law.cornell.edu/uscode/text/5/702","stext":{"head":"§702. Right of review","paras":[[0,"A person suffering legal wrong because of agency action, or adversely affected or aggrieved by agency action within the meaning of a relevant statute, is entitled to judicial review thereof. An action in a court of the United States seeking relief other than money damages and stating a claim that an agency or an officer or employee thereof acted or failed to act in an official capacity or under color of legal authority shall not be dismissed nor relief therein be denied on the ground that it is against the United States or that the United States is an indispensable party. The United States may be named as a defendant in any such action, and a judgment or decree may be entered against the United States: Provided, That any mandatory or injunctive decree shall specify the Federal officer or officers (by name or by title), and their successors in office, personally responsible for compliance. Nothing herein (1) affects other limitations on judicial review or the power or duty of the court to dismiss any action or deny relief on any other appropriate legal or equitable ground; or (2) confers authority to grant relief if any other statute that grants consent to suit expressly or impliedly forbids the relief which is sought."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/702?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§702. Right of review","tname":"Government Organization and Employees","by":{"0":"12","1":"19","2":"5"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(A)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"20","1":"30"}},{"t":"law","label":"Family Smoking Prevention and Tobacco Control Act, Pub. L. No. 111-31","url":"https://www.govinfo.gov/link/plaw/111/public/31","by":{"0":"1","1":"34","2":"1"}},{"t":"usc","label":"21 U.S.C. § 331","url":"https://www.law.cornell.edu/uscode/text/21/331","subs":["(c)"],"stext":{"head":"§331. Prohibited acts","paras":[[0,"The following acts and the causing thereof are prohibited:"],[0,"(a) The introduction or delivery for introduction into interstate commerce of any food, drug, device, tobacco product, or cosmetic that is adulterated or misbranded."],[0,"(b) The adulteration or misbranding of any food, drug, device, tobacco product, or cosmetic in interstate commerce."],[0,"(c) The receipt in interstate commerce of any food, drug, device, tobacco product, or cosmetic that is adulterated or misbranded, and the delivery or proffered delivery thereof for pay or otherwise."],[0,"(d) The introduction or delivery for introduction into interstate commerce of any article in violation of section 344, 350d, 355,,1 360bbb–3, or 364c of this title."],[0,"(e) The refusal to permit access to or copying of any record as required by section 350a, 350c, 350f(j), 350e, 354, 360bbb–3, 364a, 373, 374(a), 379aa, or 379aa–1 of this title; or the failure to establish or maintain any record, or make any report, required under section 350a, 350c(b), 350f, 350e, 354, 355(i) or (k), 360b(a)(4)(C), 360b(j), (l) or (m), 360ccc–1(i), 360e(f), 360i, 360bbb–3, 364a, 364g, 379aa, 379aa–1, 387i, or 387t of this title or the refusal to permit access to or verification or copying of any such required record; or the violation of any recordkeeping requirement under section 2223 2 of this title (except when such violation is committed by a farm)."],[0,"(f) The refusal to permit entry or inspection as authorized by section 374 of this title."],[0,"(g) The manufacture within any Territory of any food, drug, device, tobacco product, or cosmetic that is adulterated or misbranded."],[0,"(h) The giving of a guaranty or undertaking referred to in section 333(c)(2) of this title, which guaranty or undertaking is false, except by a person who relied upon a guaranty or undertaking to the same effect signed by, and containing the name and address of, the person residing in the United States from whom he received in good faith the food, drug, device, tobacco product, or cosmetic; or the giving of a guaranty or undertaking referred to in section 333(c)(3) of this title, which guaranty or undertaking is false."],[0,"(i)(1) Forging, counterfeiting, simulating, or falsely representing, or without proper authority using any mark, stamp, tag, label, or other identification device authorized or required by regulations promulgated under the provisions of section 344 or 379e of this title."],[0,"(2) Making, selling, disposing of, or keeping in possession, control, or custody, or concealing any punch, die, plate, stone, or other thing designed to print, imprint, or reproduce the trademark, trade name, or other identifying mark, imprint, or device of another or any likeness of any of the foregoing upon any drug or container or labeling thereof so as to render such drug a counterfeit drug."],[0,"(3) The doing of any act which causes a drug to be a counterfeit drug, or the sale or dispensing, or the holding for sale or dispensing, of a counterfeit drug."],[0,"(j) The using by any person to his own advantage, or revealing, other than to the Secretary or officers or employees of the Department, or to the courts when relevant in any judicial proceeding under this chapter, any information acquired under authority of section 344, 348, 350a, 350c, 355, 360, 360b, 360c, 360d, 360e, 360f, 360h, 360i, 360j, 360ccc, 360ccc–1, 360ccc–2, 374, 379, 379e, 387d, 387e, 387f, 387g, 387h, 387i, or 387t(b) of this title concerning any method or process which as a trade secret is entitled to protection; or the violating of section 346a(i)(2) of this title or any regulation issued under that section..1This paragraph does not authorize the withholding of information from either House of Congress or from, to the extent of matter within its jurisdiction, any committee or subcommittee of such committee or any joint committee of Congress or any subcommittee of such joint committee."],[0,"(k) The alteration, mutilation, destruction, obliteration, or removal of the whole or any part of the labeling of, or the doing of any other act with respect to, a food, drug, device, tobacco product, or cosmetic, if such act is done while such article is held for sale (whether or not the first sale) after shipment in interstate commerce and results in such article being adulterated or misbranded."],[0,"(l) Repealed. Pub. L. 105–115, title IV, §421, Nov. 21, 1997, 111 Stat. 2380."],[0,"(m) The sale or offering for sale of colored oleomargarine or colored margarine, or the possession or serving of colored oleomargarine or colored margarine in violation of subsections (b) or (c) of section 347 of this title."],[0,"(n) The using, in labeling, advertising or other sales promotion of any reference to any report or analysis furnished in compliance with section 374 of this title."],[0,"(o) In the case of a prescription drug distributed or offered for sale in interstate commerce, the failure of the manufacturer, packer, or distributor thereof to maintain for transmittal, or to transmit, to any practitioner licensed by applicable State law to administer such drug who makes written request for information as to such drug, true and correct copies of all printed matter which is required to be included in any package in which that drug is distributed or sold, or such other printed matter as is approved by the Secretary. Nothing in this paragraph shall be construed to exempt any person from any labeling requirement imposed by or under other provisions of this chapter."],[0,"(p) The failure to register in accordance with section 360 or 387e of this title, the failure to provide any information required by section 360(j), 360(k), 387e(i), or 387e(j) of this title, or the failure to provide a notice required by section 360(j)(2) or 387e(i)(3) of this title."],[0,"(q)(1) The failure or refusal—"],[1,"(A) to comply with any requirement prescribed under section 360h, 360j(g), 387c(b), 387g, 387h, or 387o of this title;"],[1,"(B) to furnish any notification or other material or information required by or under section 360i, 360j(g), 387d, 387i, or 387t of this title; or"],[1,"(C) to comply with a requirement under section 360l or 387m of this title."],[0,"(2) With respect to any device or tobacco product, the submission of any report that is required by or under this chapter that is false or misleading in any material respect."],[0,"(3) The failure to comply with any requirement under section 360n–2(b)(2) of this title (relating to ensuring device cybersecurity)."],[0,"(r) The movement of a device, drug, or tobacco product in violation of an order under section 334(g) of this title or the removal or alteration of any mark or label required by the order to identify the device, drug, or tobacco product as detained."],[0,"(s) The failure to provide the notice required by section 350a(c) or 350a(e) of this title, the failure to make the reports required by section 350a(f)(1)(B) of this title, the failure to retain the records required by section 350a(b)(4) of this title, or the failure to meet the requirements prescribed under section 350a(f)(3) of this title."],[0,"(t) The importation of a drug in violation of section 381(d)(1) of this title, the sale, purchase, or trade of a drug or drug sample or the offer to sell, purchase, or trade a drug or drug sample in violation of section 353(c) of this title, the sale, purchase, or trade of a coupon, the offer to sell, purchase, or trade such a coupon, or the counterfeiting of such a coupon in violation of section 353(c)(2) of this title, the distribution of a drug sample in violation of section 353(d) of this title or the failure to otherwise comply with the requirements of section 353(d) of this title, the distribution of drugs in violation of section 353(e) of this title, failure to comply with the requirements under section 360eee–1 of this title, the failure to comply with the requirements under section 360eee–3 of this title, as applicable, or the failure to otherwise comply with the requirements of section 353(e) of this title."],[0,"(u) The failure to comply with any requirements of the provisions of, or any regulations or orders of the Secretary, under section 360b(a)(4)(A), 360b(a)(4)(D), or 360b(a)(5) of this title."],[0,"(v) The introduction or delivery for introduction into interstate commerce of a dietary supplement that is unsafe under section 350b of this title."],[0,"(w) The making of a knowingly false statement in any statement, certificate of analysis, record, or report required or requested under section 381(d)(3) of this title; the failure to submit a certificate of analysis as required under such section; the failure to maintain records or to submit records or reports as required by such section; the release into interstate commerce of any article or portion thereof imported into the United States under such section or any finished product made from such article or portion, except for export in accordance with section 381(e) or 382 of this title, or with section 262(h) of title 42; or the failure to so export or to destroy such an article or portions thereof, or such a finished product."],[0,"(x) The falsification of a declaration of conformity submitted under section 360d(c) of this title or the failure or refusal to provide data or information requested by the Secretary under paragraph (3) of such section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/331?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§331. Prohibited acts","tname":"Food and Drugs","by":{"0":"20","1":"28","2":"7"}},{"t":"usc","label":"21 U.S.C. § 387a","url":"https://www.law.cornell.edu/uscode/text/21/387a","subs":["(b)"],"stext":{"head":"§387a. FDA authority over tobacco products","paras":[[0,"(a) In general"],[0,"Tobacco products, including modified risk tobacco products for which an order has been issued in accordance with section 387k of this title, shall be regulated by the Secretary under this subchapter and shall not be subject to the provisions of subchapter V."],[0,"(b) Applicability"],[0,"This subchapter shall apply to all cigarettes, cigarette tobacco, roll-your-own tobacco, and smokeless tobacco and to any other tobacco products that the Secretary by regulation deems to be subject to this subchapter. This subchapter shall also apply to any tobacco product containing nicotine that is not made or derived from tobacco."],[0,"(c) Scope"],[0,"(1) In general"],[1,"Nothing in this subchapter, or any policy issued or regulation promulgated thereunder, or in sections 101(a), 102, or 103 of title I, title II, or title III of the Family Smoking Prevention and Tobacco Control Act, shall be construed to affect, expand, or limit the Secretary's authority over (including the authority to determine whether products may be regulated), or the regulation of, products under this chapter that are not tobacco products under subchapter V or any other subchapter."],[0,"(2) Limitation of authority"],[0,"(A) In general"],[2,"The provisions of this subchapter shall not apply to tobacco leaf that is not in the possession of a manufacturer of tobacco products, or to the producers of tobacco leaf, including tobacco growers, tobacco warehouses, and tobacco grower cooperatives, nor shall any employee of the Food and Drug Administration have any authority to enter onto a farm owned by a producer of tobacco leaf without the written consent of such producer."],[0,"(B) Exception"],[2,"Notwithstanding subparagraph (A), if a producer of tobacco leaf is also a tobacco product manufacturer or controlled by a tobacco product manufacturer, the producer shall be subject to this subchapter in the producer's capacity as a manufacturer. The exception in this subparagraph shall not apply to a producer of tobacco leaf who grows tobacco under a contract with a tobacco product manufacturer and who is not otherwise engaged in the manufacturing process."],[0,"(C) Rule of construction"],[2,"Nothing in this subchapter shall be construed to grant the Secretary authority to promulgate regulations on any matter that involves the production of tobacco leaf or a producer thereof, other than activities by a manufacturer affecting production."],[0,"(d) Rulemaking procedures"],[0,"Each rulemaking under this subchapter shall be in accordance with chapter 5 of title 5. This subsection shall not be construed to affect the rulemaking provisions of section 102(a) of the Family Smoking Prevention and Tobacco Control Act [21 U.S.C. 387a–1(a)]."],[0,"(e) Center for tobacco products"],[0,"Not later than 90 days after June 22, 2009, the Secretary shall establish within the Food and Drug Administration the Center for Tobacco Products, which shall report to the Commissioner of Food and Drugs in the same manner as the other agency centers within the Food and Drug Administration. The Center shall be responsible for the implementation of this subchapter and related matters assigned by the Commissioner."],[0,"(f) Office to assist small tobacco product manufacturers"],[0,"The Secretary shall establish within the Food and Drug Administration an identifiable office to provide technical and other nonfinancial assistance to small tobacco product manufacturers to assist them in complying with the requirements of this chapter."],[0,"(g) Consultation prior to rulemaking"],[0,"Prior to promulgating rules under this subchapter, the Secretary shall endeavor to consult with other Federal agencies as appropriate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387a?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§387a. FDA authority over tobacco products","tname":"Food and Drugs","by":{"0":"2, 3","1":"5, 28"}},{"t":"usc","label":"21 U.S.C. § 387b","url":"https://www.law.cornell.edu/uscode/text/21/387b","subs":["(6)(A)"],"stext":{"head":"§387b. Adulterated tobacco products","paras":[[0,"A tobacco product shall be deemed to be adulterated if—"],[1,"(1) it consists in whole or in part of any filthy, putrid, or decomposed substance, or is otherwise contaminated by any added poisonous or added deleterious substance that may render the product injurious to health;"],[1,"(2) it has been prepared, packed, or held under insanitary conditions whereby it may have been contaminated with filth, or whereby it may have been rendered injurious to health;"],[1,"(3) its package is composed, in whole or in part, of any poisonous or deleterious substance which may render the contents injurious to health;"],[1,"(4) the manufacturer or importer of the tobacco product fails to pay a user fee assessed to such manufacturer or importer pursuant to section 387s of this title by the date specified in section 387s of this title or by the 30th day after final agency action on a resolution of any dispute as to the amount of such fee;"],[1,"(5) it is, or purports to be or is represented as, a tobacco product which is subject to a tobacco product standard established under section 387g of this title unless such tobacco product is in all respects in conformity with such standard;"],[1,"(6)(A) it is required by section 387j(a) of this title to have premarket review and does not have an order in effect under section 387j(c)(1)(A)(i) of this title; or"],[1,"(B) it is in violation of an order under section 387j(c)(1)(A) of this title;"],[1,"(7) the methods used in, or the facilities or controls used for, its manufacture, packing, or storage are not in conformity with applicable requirements under section 387f(e)(1) of this title or an applicable condition prescribed by an order under section 387f(e)(2) of this title; or"],[1,"(8) it is in violation of section 387k of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387b?type=usc&year=mostrecent&link-type=html"},"head":"§387b. Adulterated tobacco products","tname":"Food and Drugs","by":{"0":"20","1":"28","2":"7"}},{"t":"usc","label":"21 U.S.C. § 387f","url":"https://www.law.cornell.edu/uscode/text/21/387f","subs":["(c)"],"stext":{"head":"§387f. General provisions respecting control of tobacco products","paras":[[0,"(a) In general"],[0,"Any requirement established by or under section 387b, 387c, 387e, or 387i of this title applicable to a tobacco product shall apply to such tobacco product until the applicability of the requirement to the tobacco product has been changed by action taken under section 387g of this title, section 387j of this title, section 387k of this title, or subsection (d) of this section, and any requirement established by or under section 387b, 387c, 387e, or 387i of this title which is inconsistent with a requirement imposed on such tobacco product under section 387g of this title, section 387j of this title, section 387k of this title, or subsection (d) of this section shall not apply to such tobacco product."],[0,"(b) Information on public access and comment"],[0,"Each notice of proposed rulemaking or other notification under section 387g, 387h, 387i, 387j, or 387k of this title or under this section, any other notice which is published in the Federal Register with respect to any other action taken under any such section and which states the reasons for such action, and each publication of findings required to be made in connection with rulemaking under any such section shall set forth—"],[1,"(1) the manner in which interested persons may examine data and other information on which the notice or findings is 1 based; and"],[1,"(2) the period within which interested persons may present their comments on the notice or findings (including the need therefore) orally or in writing, which period shall be at least 60 days but may not exceed 90 days unless the time is extended by the Secretary by a notice published in the Federal Register stating good cause therefore."],[0,"(c) Limited confidentiality of information"],[0,"Any information reported to or otherwise obtained by the Secretary or the Secretary's representative under section 387c, 387d, 387g, 387h, 387i, 387j, 387k, or 374 of this title, or under subsection (e) or (f) of this section, which is exempt from disclosure under subsection (a) of section 552 of title 5 by reason of subsection (b)(4) of that section shall be considered confidential and shall not be disclosed, except that the information may be disclosed to other officers or employees concerned with carrying out this subchapter, or when relevant in any proceeding under this subchapter."],[0,"(d) Restrictions"],[0,"(1) In general"],[1,"The Secretary may by regulation require restrictions on the sale and distribution of a tobacco product, including restrictions on the access to, and the advertising and promotion of, the tobacco product, if the Secretary determines that such regulation would be appropriate for the protection of the public health. The Secretary may by regulation impose restrictions on the advertising and promotion of a tobacco product consistent with and to full extent permitted by the first amendment to the Constitution. The finding as to whether such regulation would be appropriate for the protection of the public health shall be determined with respect to the risks and benefits to the population as a whole, including users and nonusers of the tobacco product, and taking into account—"],[2,"(A) the increased or decreased likelihood that existing users of tobacco products will stop using such products; and"],[2,"(B) the increased or decreased likelihood that those who do not use tobacco products will start using such products."],[1,"No such regulation may require that the sale or distribution of a tobacco product be limited to the written or oral authorization of a practitioner licensed by law to prescribe medical products."],[0,"(2) Label statements"],[1,"The label of a tobacco product shall bear such appropriate statements of the restrictions required by a regulation under subsection (a) as the Secretary may in such regulation prescribe."],[0,"(3) Limitations"],[0,"(A) In general"],[2,"No restrictions under paragraph (1) may—"],[3,"(i) prohibit the sale of any tobacco product in face-to-face transactions by a specific category of retail outlets; or"],[3,"(ii) establish a minimum age of sale of tobacco products to any person older than 21 years of age."],[0,"(B) Matchbooks"],[2,"For purposes of any regulations issued by the Secretary, matchbooks of conventional size containing not more than 20 paper matches, and which are customarily given away for free with the purchase of tobacco products, shall be considered as adult-written publications which shall be permitted to contain advertising. Notwithstanding the preceding sentence, if the Secretary finds that such treatment of matchbooks is not appropriate for the protection of the public health, the Secretary may determine by regulation that matchbooks shall not be considered adult-written publications."],[0,"(4) Remote sales"],[0,"(A) In general"],[2,"The Secretary shall—"],[3,"(i) within 18 months after June 22, 2009, promulgate regulations regarding the sale and distribution of tobacco products that occur through means other than a direct, face-to-face exchange between a retailer and a consumer in order to prevent the sale and distribution of tobacco products to individuals who have not attained the minimum age established by applicable law for the purchase of such products, including requirements for age verification; and"],[3,"(ii) within 2 years after June 22, 2009, issue regulations to address the promotion and marketing of tobacco products that are sold or distributed through means other than a direct, face-to-face exchange between a retailer and a consumer in order to protect individuals who have not attained the minimum age established by applicable law for the purchase of such products."],[0,"(B) Relation to other authority"],[2,"Nothing in this paragraph limits the authority of the Secretary to take additional actions under the other paragraphs of this subsection."],[0,"(5) Minimum age of sale"],[1,"It shall be unlawful for any retailer to sell a tobacco product to any person younger than 21 years of age."],[0,"(e) Good manufacturing practice requirements"],[0,"(1) Methods, facilities, and controls to conform"],[0,"(A) In general"],[2,"In applying manufacturing restrictions to tobacco, the Secretary shall, in accordance with subparagraph (B), prescribe regulations (which may differ based on the type of tobacco product involved) requiring that the methods used in, and the facilities and controls used for, the manufacture, preproduction design validation (including a process to assess the performance of a tobacco product), packing, and storage of a tobacco product conform to current good manufacturing practice, or hazard analysis and critical control point methodology, as prescribed in such regulations to assure that the public health is protected and that the tobacco product is in compliance with this subchapter. Such regulations may provide for the testing of raw tobacco for pesticide chemical residues regardless of whether a tolerance for such chemical residues has been established."],[0,"(B) Requirements"],[2,"The Secretary shall—"],[3,"(i) before promulgating any regulation under subparagraph (A), afford the Tobacco Products Scientific Advisory Committee an opportunity to submit recommendations with respect to the regulation proposed to be promulgated;"],[3,"(ii) before promulgating any regulation under subparagraph (A), afford opportunity for an oral hearing;"],[3,"(iii) provide the Tobacco Products Scientific Advisory Committee a reasonable time to make its recommendation with respect to proposed regulations under subparagraph (A);"],[3,"(iv) in establishing the effective date of a regulation promulgated under this subsection, take into account the differences in the manner in which the different types of tobacco products have historically been produced, the financial resources of the different tobacco product manufacturers, and the state of their existing manufacturing facilities, and shall provide for a reasonable period of time for such manufacturers to conform to good manufacturing practices; and"],[3,"(v) not require any small tobacco product manufacturer to comply with a regulation under subparagraph (A) for at least 4 years following the effective date established by the Secretary for such regulation."],[0,"(2) Exemptions; variances"],[0,"(A) Petition"],[2,"Any person subject to any requirement prescribed under paragraph (1) may petition the Secretary for a permanent or temporary exemption or variance from such requirement. Such a petition shall be submitted to the Secretary in such form and manner as the Secretary shall prescribe and shall—"],[3,"(i) in the case of a petition for an exemption from a requirement, set forth the basis for the petitioner's determination that compliance with the requirement is not required to assure that the tobacco product will be in compliance with this subchapter;"],[3,"(ii) in the case of a petition for a variance from a requirement, set forth the methods proposed to be used in, and the facilities and controls proposed to be used for, the manufacture, packing, and storage of the tobacco product in lieu of the methods, facilities, and controls prescribed by the requirement; and"],[3,"(iii) contain such other information as the Secretary shall prescribe."],[0,"(B) Referral to the Tobacco Products Scientific Advisory Committee"],[2,"The Secretary may refer to the Tobacco Products Scientific Advisory Committee any petition submitted under subparagraph (A). The Tobacco Products Scientific Advisory Committee shall report its recommendations to the Secretary with respect to a petition referred to it within 60 days after the date of the petition's referral. Within 60 days after—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387f?type=usc&year=mostrecent&link-type=html"},"head":"§387f. General provisions respecting control of tobacco products","tname":"Food and Drugs","by":{"0":"18, 19","1":"28, 30","2":"9"}},{"t":"usc","label":"21 U.S.C. § 387g","url":"https://www.law.cornell.edu/uscode/text/21/387g","stext":{"head":"§387g. Tobacco product standards","paras":[[0,"(a) In general"],[0,"(1) Special rules"],[0,"(A) Special rule for cigarettes"],[2,"Beginning 3 months after June 22, 2009, a cigarette or any of its component parts (including the tobacco, filter, or paper) shall not contain, as a constituent (including a smoke constituent) or additive, an artificial or natural flavor (other than tobacco or menthol) or an herb or spice, including strawberry, grape, orange, clove, cinnamon, pineapple, vanilla, coconut, licorice, cocoa, chocolate, cherry, or coffee, that is a characterizing flavor of the tobacco product or tobacco smoke. Nothing in this subparagraph shall be construed to limit the Secretary's authority to take action under this section or other sections of this chapter applicable to menthol or any artificial or natural flavor, herb, or spice not specified in this subparagraph."],[0,"(B) Additional special rule"],[2,"Beginning 2 years after June 22, 2009, a tobacco product manufacturer shall not use tobacco, including foreign grown tobacco, that contains a pesticide chemical residue that is at a level greater than is specified by any tolerance applicable under Federal law to domestically grown tobacco."],[0,"(2) Revision of tobacco product standards"],[1,"The Secretary may revise the tobacco product standards in paragraph (1) in accordance with subsection (c)."],[0,"(3) Tobacco product standards"],[0,"(A) In general"],[2,"The Secretary may adopt tobacco product standards in addition to those in paragraph (1) if the Secretary finds that a tobacco product standard is appropriate for the protection of the public health."],[0,"(B) Determinations"],[0,"(i) Considerations"],[3,"In making a finding described in subparagraph (A), the Secretary shall consider scientific evidence concerning—"],[4,"(I) the risks and benefits to the population as a whole, including users and nonusers of tobacco products, of the proposed standard;"],[4,"(II) the increased or decreased likelihood that existing users of tobacco products will stop using such products; and"],[4,"(III) the increased or decreased likelihood that those who do not use tobacco products will start using such products."],[0,"(ii) Additional considerations"],[3,"In the event that the Secretary makes a determination, set forth in a proposed tobacco product standard in a proposed rule, that it is appropriate for the protection of public health to require the reduction or elimination of an additive, constituent (including a smoke constituent), or other component of a tobacco product because the Secretary has found that the additive, constituent, or other component is or may be harmful, any party objecting to the proposed standard on the ground that the proposed standard will not reduce or eliminate the risk of illness or injury may provide for the Secretary's consideration scientific evidence that demonstrates that the proposed standard will not reduce or eliminate the risk of illness or injury."],[0,"(4) Content of tobacco product standards"],[1,"A tobacco product standard established under this section for a tobacco product—"],[2,"(A) shall include provisions that are appropriate for the protection of the public health, including provisions, where appropriate—"],[3,"(i) for nicotine yields of the product;"],[3,"(ii) for the reduction or elimination of other constituents, including smoke constituents, or harmful components of the product; or"],[3,"(iii) relating to any other requirement under subparagraph (B);"],[2,"(B) shall, where appropriate for the protection of the public health, include—"],[3,"(i) provisions respecting the construction, components, ingredients, additives, constituents, including smoke constituents, and properties of the tobacco product;"],[3,"(ii) provisions for the testing (on a sample basis or, if necessary, on an individual basis) of the tobacco product;"],[3,"(iii) provisions for the measurement of the tobacco product characteristics of the tobacco product;"],[3,"(iv) provisions requiring that the results of each or of certain of the tests of the tobacco product required to be made under clause (ii) show that the tobacco product is in conformity with the portions of the standard for which the test or tests were required; and"],[3,"(v) a provision requiring that the sale and distribution of the tobacco product be restricted but only to the extent that the sale and distribution of a tobacco product may be restricted under a regulation under section 387f(d) of this title;"],[2,"(C) shall, where appropriate, require the use and prescribe the form and content of labeling for the proper use of the tobacco product; and"],[2,"(D) shall require tobacco products containing foreign-grown tobacco to meet the same standards applicable to tobacco products containing domestically grown tobacco."],[0,"(5) Periodic reevaluation of tobacco product standards"],[1,"The Secretary shall provide for periodic evaluation of tobacco product standards established under this section to determine whether such standards should be changed to reflect new medical, scientific, or other technological data. The Secretary may provide for testing under paragraph (4)(B) by any person."],[0,"(6) Involvement of other agencies; informed persons"],[1,"In carrying out duties under this section, the Secretary shall endeavor to—"],[2,"(A) use personnel, facilities, and other technical support available in other Federal agencies;"],[2,"(B) consult with other Federal agencies concerned with standard setting and other nationally or internationally recognized standard-setting entities; and"],[2,"(C) invite appropriate participation, through joint or other conferences, workshops, or other means, by informed persons representative of scientific, professional, industry, agricultural, or consumer organizations who in the Secretary's judgment can make a significant contribution."],[0,"(b) Considerations by Secretary"],[0,"(1) Technical achievability"],[1,"The Secretary shall consider information submitted in connection with a proposed standard regarding the technical achievability of compliance with such standard, including with regard to any differences related to the technical achievability of compliance with such standard for products in the same class containing nicotine not made or derived from tobacco and products containing nicotine made or derived from tobacco."],[0,"(2) Other considerations"],[1,"The Secretary shall consider all other information submitted in connection with a proposed standard, including information concerning the countervailing effects of the tobacco product standard on the health of adolescent tobacco users, adult tobacco users, or nontobacco users, such as the creation of a significant demand for contraband or other tobacco products that do not meet the requirements of this subchapter and the significance of such demand."],[0,"(c) Proposed standards"],[0,"(1) In general"],[1,"The Secretary shall publish in the Federal Register a notice of proposed rulemaking for the establishment, amendment, or revocation of any tobacco product standard."],[0,"(2) Requirements of notice"],[1,"A notice of proposed rulemaking for the establishment or amendment of a tobacco product standard for a tobacco product shall—"],[2,"(A) set forth a finding with supporting justification that the tobacco product standard is appropriate for the protection of the public health;"],[2,"(B) invite interested persons to submit a draft or proposed tobacco product standard for consideration by the Secretary;"],[2,"(C) invite interested persons to submit comments on structuring the standard so that it does not advantage foreign-grown tobacco over domestically grown tobacco; and"],[2,"(D) invite the Secretary of Agriculture to provide any information or analysis which the Secretary of Agriculture believes is relevant to the proposed tobacco product standard."],[0,"(3) Finding"],[1,"A notice of proposed rulemaking for the revocation of a tobacco product standard shall set forth a finding with supporting justification that the tobacco product standard is no longer appropriate for the protection of the public health."],[0,"(4) Comment"],[1,"The Secretary shall provide for a comment period of not less than 60 days."],[0,"(d) Promulgation"],[0,"(1) In general"],[1,"After the expiration of the period for comment on a notice of proposed rulemaking published under subsection (c) respecting a tobacco product standard and after consideration of comments submitted under subsections (b) and (c) and any report from the Tobacco Products Scientific Advisory Committee, the Secretary shall—"],[2,"(A) if the Secretary determines that the standard would be appropriate for the protection of the public health, promulgate a regulation establishing a tobacco product standard and publish in the Federal Register findings on the matters referred to in subsection (c); or"],[2,"(B) publish a notice terminating the proceeding for the development of the standard together with the reasons for such termination."],[0,"(2) Effective date"],[1,"A regulation establishing a tobacco product standard shall set forth the date or dates upon which the standard shall take effect, but no such regulation may take effect before 1 year after the date of its publication unless the Secretary determines that an earlier effective date is necessary for the protection of the public health. Such date or dates shall be established so as to minimize, consistent with the public health, economic loss to, and disruption or dislocation of, domestic and international trade. In establishing such effective date or dates, the Secretary shall consider information submitted in connection with a proposed product standard by interested parties, including manufacturers and tobacco growers, regarding the technical achievability of compliance with the standard, and including information concerning the existence of patents that make it impossible to comply in the timeframe envisioned in the proposed standard. If the Secretary determines, based on the Secretary's evaluation of submitted comments, that a product standard can be met only by manufacturers requiring substantial changes to the methods of farming the domestically grown tobacco used by the manufacturer, the effective date of that product standard shall be not less than 2 years after the date of publication of the final regulation establishing the standard."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387g?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§387g. Tobacco product standards","tname":"Food and Drugs","by":{"0":"9","1":"29"}},{"t":"usc","label":"21 U.S.C. § 387j","url":"https://www.law.cornell.edu/uscode/text/21/387j","subs":["(a)(1)","(a)(2)","(b)","(b)(2)(B)","(c)","(c)(1)(A)","(c)(2)","(c)(2)(A)","(c)(3)","(c)(4)","(d)(1)","(d)(1)(A)","(d)(2)","(e)(2)"],"stext":{"head":"§387j. Application for review of certain tobacco products","paras":[[0,"(a) In general"],[0,"(1) New tobacco product defined"],[1,"For purposes of this section the term \"new tobacco product\" means—"],[2,"(A) any tobacco product (including those products in test markets) that was not commercially marketed in the United States as of February 15, 2007; or"],[2,"(B) any modification (including a change in design, any component, any part, or any constituent, including a smoke constituent, or in the content, delivery or form of nicotine, or any other additive or ingredient) of a tobacco product where the modified product was commercially marketed in the United States after February 15, 2007."],[0,"(2) Premarket review required"],[0,"(A) New products"],[2,"An order under subsection (c)(1)(A)(i) for a new tobacco product is required unless—"],[3,"(i) the manufacturer has submitted a report under section 387e(j) of this title; and the Secretary has issued an order that the tobacco product—"],[4,"(I) is substantially equivalent to a tobacco product commercially marketed (other than for test marketing) in the United States as of February 15, 2007; and"],[4,"(II) is in compliance with the requirements of this chapter; or"],[3,"(ii) the tobacco product is exempt from the requirements of section 387e(j) of this title pursuant to a regulation issued under section 387e(j)(3) of this title."],[0,"(B) Application to certain post-February 15, 2007, products"],[2,"Subparagraph (A) shall not apply to a tobacco product—"],[3,"(i) that was first introduced or delivered for introduction into interstate commerce for commercial distribution in the United States after February 15, 2007, and prior to the date that is 21 months after June 22, 2009; and"],[3,"(ii) for which a report was submitted under section 387e(j) of this title within such 21-month period,"],[2,"except that subparagraph (A) shall apply to the tobacco product if the Secretary issues an order that the tobacco product is not substantially equivalent."],[0,"(3) Substantially equivalent defined"],[0,"(A) In general"],[2,"In this section and section 387e(j) of this title, the term \"substantially equivalent\" or \"substantial equivalence\" means, with respect to the tobacco product being compared to the predicate tobacco product, that the Secretary by order has found that the tobacco product—"],[3,"(i) has the same characteristics as the predicate tobacco product; or"],[3,"(ii) has different characteristics and the information submitted contains information, including clinical data if deemed necessary by the Secretary, that demonstrates that it is not appropriate to regulate the product under this section because the product does not raise different questions of public health."],[0,"(B) Characteristics"],[2,"In subparagraph (A), the term \"characteristics\" means the materials, ingredients, design, composition, heating source, or other features of a tobacco product."],[0,"(C) Limitation"],[2,"A tobacco product may not be found to be substantially equivalent to a predicate tobacco product that has been removed from the market at the initiative of the Secretary or that has been determined by a judicial order to be misbranded or adulterated."],[0,"(4) Health information"],[0,"(A) Summary"],[2,"As part of a submission under section 387e(j) of this title respecting a tobacco product, the person required to file a premarket notification under such section shall provide an adequate summary of any health information related to the tobacco product or state that such information will be made available upon request by any person."],[0,"(B) Required information"],[2,"Any summary under subparagraph (A) respecting a tobacco product shall contain detailed information regarding data concerning adverse health effects and shall be made available to the public by the Secretary within 30 days of the issuance of a determination that such tobacco product is substantially equivalent to another tobacco product."],[0,"(b) Application"],[0,"(1) Contents"],[1,"An application under this section shall contain—"],[2,"(A) full reports of all information, published or known to, or which should reasonably be known to, the applicant, concerning investigations which have been made to show the health risks of such tobacco product and whether such tobacco product presents less risk than other tobacco products;"],[2,"(B) a full statement of the components, ingredients, additives, and properties, and of the principle or principles of operation, of such tobacco product;"],[2,"(C) a full description of the methods used in, and the facilities and controls used for, the manufacture, processing, and, when relevant, packing and installation of, such tobacco product;"],[2,"(D) an identifying reference to any tobacco product standard under section 387g of this title which would be applicable to any aspect of such tobacco product, and either adequate information to show that such aspect of such tobacco product fully meets such tobacco product standard or adequate information to justify any deviation from such standard;"],[2,"(E) such samples of such tobacco product and of components thereof as the Secretary may reasonably require;"],[2,"(F) specimens of the labeling proposed to be used for such tobacco product; and"],[2,"(G) such other information relevant to the subject matter of the application as the Secretary may require."],[0,"(2) Referral to Tobacco Products Scientific Advisory Committee"],[1,"Upon receipt of an application meeting the requirements set forth in paragraph (1), the Secretary—"],[2,"(A) may, on the Secretary's own initiative; or"],[2,"(B) may, upon the request of an applicant,"],[1,"refer such application to the Tobacco Products Scientific Advisory Committee for reference and for submission (within such period as the Secretary may establish) of a report and recommendation respecting the application, together with all underlying data and the reasons or basis for the recommendation."],[0,"(c) Action on application"],[0,"(1) Deadline"],[0,"(A) In general"],[2,"As promptly as possible, but in no event later than 180 days after the receipt of an application under subsection (b), the Secretary, after considering the report and recommendation submitted under subsection (b)(2), shall—"],[3,"(i) issue an order that the new product may be introduced or delivered for introduction into interstate commerce if the Secretary finds that none of the grounds specified in paragraph (2) of this subsection applies; or"],[3,"(ii) issue an order that the new product may not be introduced or delivered for introduction into interstate commerce if the Secretary finds (and sets forth the basis for such finding as part of or accompanying such denial) that 1 or more grounds for denial specified in paragraph (2) of this subsection apply."],[0,"(B) Restrictions on sale and distribution"],[2,"An order under subparagraph (A)(i) may require that the sale and distribution of the tobacco product be restricted but only to the extent that the sale and distribution of a tobacco product may be restricted under a regulation under section 387f(d) of this title."],[0,"(2) Denial of application"],[1,"The Secretary shall deny an application submitted under subsection (b) if, upon the basis of the information submitted to the Secretary as part of the application and any other information before the Secretary with respect to such tobacco product, the Secretary finds that—"],[2,"(A) there is a lack of a showing that permitting such tobacco product to be marketed would be appropriate for the protection of the public health;"],[2,"(B) the methods used in, or the facilities or controls used for, the manufacture, processing, or packing of such tobacco product do not conform to the requirements of section 387f(e) of this title;"],[2,"(C) based on a fair evaluation of all material facts, the proposed labeling is false or misleading in any particular; or"],[2,"(D) such tobacco product is not shown to conform in all respects to a tobacco product standard in effect under section 387g of this title, and there is a lack of adequate information to justify the deviation from such standard."],[0,"(3) Denial information"],[1,"Any denial of an application shall, insofar as the Secretary determines to be practicable, be accompanied by a statement informing the applicant of the measures required to remove such application from deniable form (which measures may include further research by the applicant in accordance with 1 or more protocols prescribed by the Secretary)."],[0,"(4) Basis for finding"],[1,"For purposes of this section, the finding as to whether the marketing of a tobacco product for which an application has been submitted is appropriate for the protection of the public health shall be determined with respect to the risks and benefits to the population as a whole, including users and nonusers of the tobacco product, and taking into account—"],[2,"(A) the increased or decreased likelihood that existing users of tobacco products will stop using such products; and"],[2,"(B) the increased or decreased likelihood that those who do not use tobacco products will start using such products."],[0,"(5) Basis for action"],[0,"(A) Investigations"],[2,"For purposes of paragraph (2)(A), whether permitting a tobacco product to be marketed would be appropriate for the protection of the public health shall, when appropriate, be determined on the basis of well-controlled investigations, which may include 1 or more clinical investigations by experts qualified by training and experience to evaluate the tobacco product."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387j?type=usc&year=mostrecent&link-type=html"},"op":7,"ar":1,"head":"§387j. Application for review of certain tobacco products","tname":"Food and Drugs","by":{"0":"2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2","1":"5, 22, 25, 27, 29, 31, 32, 36","2":"6, 7, 6, 8, 9, 7, 11, 7, 9"}},{"t":"usc","label":"21 U.S.C. § 387l","url":"https://www.law.cornell.edu/uscode/text/21/387l","subs":["(a)(1)","(a)(1)(B)","(b)","(a)"],"stext":{"head":"§387l. Judicial review","paras":[[0,"(a) Right to review"],[0,"(1) In general"],[1,"Not later than 30 days after—"],[2,"(A) the promulgation of a regulation under section 387g of this title establishing, amending, or revoking a tobacco product standard; or"],[2,"(B) a denial of an application under section 387j(c) of this title,"],[1,"any person adversely affected by such regulation or denial may file a petition for judicial review of such regulation or denial with the United States Court of Appeals for the District of Columbia or for the circuit in which such person resides or has their principal place of business."],[0,"(2) Requirements"],[0,"(A) Copy of petition"],[2,"A copy of the petition filed under paragraph (1) shall be transmitted by the clerk of the court involved to the Secretary."],[0,"(B) Record of proceedings"],[2,"On receipt of a petition under subparagraph (A), the Secretary shall file in the court in which such petition was filed—"],[3,"(i) the record of the proceedings on which the regulation or order was based; and"],[3,"(ii) a statement of the reasons for the issuance of such a regulation or order."],[0,"(C) Definition of record"],[2,"In this section, the term \"record\" means—"],[3,"(i) all notices and other matter published in the Federal Register with respect to the regulation or order reviewed;"],[3,"(ii) all information submitted to the Secretary with respect to such regulation or order;"],[3,"(iii) proceedings of any panel or advisory committee with respect to such regulation or order;"],[3,"(iv) any hearing held with respect to such regulation or order; and"],[3,"(v) any other information identified by the Secretary, in the administrative proceeding held with respect to such regulation or order, as being relevant to such regulation or order."],[0,"(b) Standard of review"],[0,"Upon the filing of the petition under subsection (a) for judicial review of a regulation or order, the court shall have jurisdiction to review the regulation or order in accordance with chapter 7 of title 5 and to grant appropriate relief, including interim relief, as provided for in such chapter. A regulation or denial described in subsection (a) shall be reviewed in accordance with section 706(2)(A) of title 5."],[0,"(c) Finality of judgment"],[0,"The judgment of the court affirming or setting aside, in whole or in part, any regulation or order shall be final, subject to review by the Supreme Court of the United States upon certiorari or certification, as provided in section 1254 of title 28."],[0,"(d) Other remedies"],[0,"The remedies provided for in this section shall be in addition to, and not in lieu of, any other remedies provided by law."],[0,"(e) Regulations and orders must recite basis in record"],[0,"To facilitate judicial review, a regulation or order issued under section 387f, 387g, 387h, 387i, 387j, or 387p of this title shall contain a statement of the reasons for the issuance of such regulation or order in the record of the proceedings held in connection with its issuance."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/387l?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§387l. Judicial review","tname":"Food and Drugs","by":{"0":"2, 2, 2","1":"1, 7, 10, 11, 19, 25, 27, 30, 35, 38, 43, 47, 48, 49","2":"11, 4, 5, 11-13, 18, 20, 22, 9, 6"}},{"t":"usc","label":"21 U.S.C. § 393","url":"https://www.law.cornell.edu/uscode/text/21/393","subs":["(d)(2)"],"by":{"0":"2"}},{"t":"usc","label":"5 U.S.C. § 7123","url":"https://www.law.cornell.edu/uscode/text/5/7123","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"15 U.S.C. § 15","url":"https://www.law.cornell.edu/uscode/text/15/15","subs":["(a)"],"by":{"0":"31"}},{"t":"usc","label":"15 U.S.C. § 1640","url":"https://www.law.cornell.edu/uscode/text/15/1640","subs":["(e)"],"by":{"0":"36"}},{"t":"usc","label":"15 U.S.C. § 77i","url":"https://www.law.cornell.edu/uscode/text/15/77i","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"15 U.S.C. § 80a-42","url":"https://www.law.cornell.edu/uscode/text/15/80a-42","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"15 U.S.C. § 80b-13","url":"https://www.law.cornell.edu/uscode/text/15/80b-13","subs":["(a)"],"by":{"0":"37","2":"18"}},{"t":"usc","label":"15 U.S.C. § 1710","url":"https://www.law.cornell.edu/uscode/text/15/1710","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"18 U.S.C. § 2334","url":"https://www.law.cornell.edu/uscode/text/18/2334","subs":["(a)"],"by":{"0":"33"}},{"t":"usc","label":"20 U.S.C. § 6083","url":"https://www.law.cornell.edu/uscode/text/20/6083","by":{"0":"37"}},{"t":"usc","label":"20 U.S.C. § 7973","url":"https://www.law.cornell.edu/uscode/text/20/7973","subs":["(e)(5)"],"by":{"0":"37"}},{"t":"usc","label":"21 U.S.C. § 321","url":"https://www.law.cornell.edu/uscode/text/21/321","subs":["(x)"],"by":{"0":"23"}},{"t":"usc","label":"21 U.S.C. § 346a","url":"https://www.law.cornell.edu/uscode/text/21/346a","subs":["(h)(1)"],"by":{"0":"37"}},{"t":"usc","label":"21 U.S.C. § 348","url":"https://www.law.cornell.edu/uscode/text/21/348","subs":["(g)(1)"],"by":{"0":"37"}},{"t":"usc","label":"21 U.S.C. § 360g","url":"https://www.law.cornell.edu/uscode/text/21/360g","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"21 U.S.C. § 457","url":"https://www.law.cornell.edu/uscode/text/21/457","subs":["(d)"],"by":{"0":"37"}},{"t":"usc","label":"21 U.S.C. § 607","url":"https://www.law.cornell.edu/uscode/text/21/607","subs":["(e)"],"by":{"0":"37"}},{"t":"usc","label":"21 U.S.C. § 1036","url":"https://www.law.cornell.edu/uscode/text/21/1036","subs":["(b)"],"by":{"0":"37"}},{"t":"usc","label":"22 U.S.C. § 6761","url":"https://www.law.cornell.edu/uscode/text/22/6761","subs":["(a)(5)"],"by":{"0":"37"}},{"t":"usc","label":"26 U.S.C. § 7482","url":"https://www.law.cornell.edu/uscode/text/26/7482","subs":["(b)(2)","(b)(1)"],"stext":{"head":"§7482. Courts of review","paras":[[0,"(a) Jurisdiction"],[0,"(1) In general"],[1,"The United States Courts of Appeals (other than the United States Court of Appeals for the Federal Circuit) shall have exclusive jurisdiction to review the decisions of the Tax Court, except as provided in section 1254 of Title 28 of the United States Code, in the same manner and to the same extent as decisions of the district courts in civil actions tried without a jury; and the judgment of any such court shall be final, except that it shall be subject to review by the Supreme Court of the United States upon certiorari, in the manner provided in section 1254 of Title 28 of the United States Code."],[0,"(2) Interlocutory orders"],[0,"(A) In general"],[2,"When any judge of the Tax Court includes in an interlocutory order a statement that a controlling question of law is involved with respect to which there is a substantial ground for difference of opinion and that an immediate appeal from that order may materially advance the ultimate termination of the litigation, the United States Court of Appeals may, in its discretion, permit an appeal to be taken from such order, if application is made to it within 10 days after the entry of such order. Neither the application for nor the granting of an appeal under this paragraph shall stay proceedings in the Tax Court, unless a stay is ordered by a judge of the Tax Court or by the United States Court of Appeals which has jurisdiction of the appeal or a judge of that court."],[0,"(B) Order treated as Tax Court decision"],[2,"For purposes of subsections (b) and (c), an order described in this paragraph shall be treated as a decision of the Tax Court."],[0,"(C) Venue for review of subsequent proceedings"],[2,"If a United States Court of Appeals permits an appeal to be taken from an order described in subparagraph (A), except as provided in subsection (b)(2), any subsequent review of the decision of the Tax Court in the proceeding shall be made by such Court of Appeals."],[0,"(3) Certain orders entered under section 6213(a)"],[1,"An order of the Tax Court which is entered under authority of section 6213(a) and which resolves a proceeding to restrain assessment or collection shall be treated as a decision of the Tax Court for purposes of this section and shall be subject to the same review by the United States Court of Appeals as a similar order of a district court."],[0,"(b) Venue"],[0,"(1) In general"],[1,"Except as otherwise provided in paragraphs (2) and (3), such decisions may be reviewed by the United States court of appeals for the circuit in which is located—"],[2,"(A) in the case of a petitioner seeking redetermination of tax liability other than a corporation, the legal residence of the petitioner,"],[2,"(B) in the case of a corporation seeking redetermination of tax liability, the principal place of business or principal office or agency of the corporation, or, if it has no principal place of business or principal office or agency in any judicial circuit, then the office to which was made the return of the tax in respect of which the liability arises,"],[2,"(C) in the case of a person seeking a declaratory decision under section 7476, the principal place of business, or principal office or agency of the employer,"],[2,"(D) in the case of an organization seeking a declaratory decision under section 7428, the principal office or agency of the organization,"],[2,"(E) in the case of a petition under section 6234, the principal place of business of the partnership,"],[2,"(F) in the case of a petition under section 6015(e), the legal residence of the petitioner, or"],[2,"(G) in the case of a petition under section 6320 or 6330—"],[3,"(i) the legal residence of the petitioner if the petitioner is an individual, and"],[3,"(ii) the principal place of business or principal office or agency if the petitioner is an entity other than an individual."],[1,"If for any reason no subparagraph of the preceding sentence applies, then such decisions may be reviewed by the Court of Appeals for the District of Columbia. For purposes of this paragraph, the legal residence, principal place of business, or principal office or agency referred to herein shall be determined as of the time the petition seeking redetermination of tax liability was filed with the Tax Court or as of the time the petition seeking a declaratory decision under section 7428 or 7476, or the petition under section 6234, was filed with the Tax Court."],[0,"(2) By agreement"],[1,"Notwithstanding the provisions of paragraph (1), such decisions may be reviewed by any United States Court of Appeals which may be designated by the Secretary and the taxpayer by stipulation in writing."],[0,"(3) Declaratory judgment actions relating to status of certain governmental obligations"],[1,"In the case of any decision of the Tax Court in a proceeding under section 7478, such decision may only be reviewed by the Court of Appeals for the District of Columbia."],[0,"(c) Powers"],[0,"(1) To affirm, modify, or reverse"],[1,"Upon such review, such courts shall have power to affirm or, if the decision of the Tax Court is not in accordance with law, to modify or to reverse the decision of the Tax Court, with or without remanding the case for a rehearing, as justice may require."],[0,"(2) To make rules"],[1,"Rules for review of decisions of the Tax Court shall be those prescribed by the Supreme Court under section 2072 of title 28 of the United States Code."],[0,"(3) To require additional security"],[1,"Nothing in section 7483 shall be construed as relieving the petitioner from making or filing such undertakings as the court may require as a condition of or in connection with the review."],[0,"(4) To impose penalties"],[1,"The United States Court of Appeals and the Supreme Court shall have the power to require the taxpayer to pay to the United States a penalty in any case where the decision of the Tax Court is affirmed and it appears that the appeal was instituted or maintained primarily for delay or that the taxpayer's position in the appeal is frivolous or groundless."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7482?type=usc&year=mostrecent&link-type=html"},"head":"§7482. Courts of review","tname":"Internal Revenue Code","by":{"0":"36","2":"18"}},{"t":"usc","label":"28 U.S.C. § 1391","url":"https://www.law.cornell.edu/uscode/text/28/1391","subs":["(c)(3)","(e)(1)(A)","(e)(1)(C)"],"stext":{"head":"§1391. Venue generally","paras":[[0,"(a) Applicability of Section.—Except as otherwise provided by law—"],[1,"(1) this section shall govern the venue of all civil actions brought in district courts of the United States; and"],[1,"(2) the proper venue for a civil action shall be determined without regard to whether the action is local or transitory in nature."],[0,"(b) Venue in General.—A civil action may be brought in—"],[1,"(1) a judicial district in which any defendant resides, if all defendants are residents of the State in which the district is located;"],[1,"(2) a judicial district in which a substantial part of the events or omissions giving rise to the claim occurred, or a substantial part of property that is the subject of the action is situated; or"],[1,"(3) if there is no district in which an action may otherwise be brought as provided in this section, any judicial district in which any defendant is subject to the court's personal jurisdiction with respect to such action."],[0,"(c) Residency.—For all venue purposes—"],[1,"(1) a natural person, including an alien lawfully admitted for permanent residence in the United States, shall be deemed to reside in the judicial district in which that person is domiciled;"],[1,"(2) an entity with the capacity to sue and be sued in its common name under applicable law, whether or not incorporated, shall be deemed to reside, if a defendant, in any judicial district in which such defendant is subject to the court's personal jurisdiction with respect to the civil action in question and, if a plaintiff, only in the judicial district in which it maintains its principal place of business; and"],[1,"(3) a defendant not resident in the United States may be sued in any judicial district, and the joinder of such a defendant shall be disregarded in determining where the action may be brought with respect to other defendants."],[0,"(d) Residency of Corporations in States With Multiple Districts.—For purposes of venue under this chapter, in a State which has more than one judicial district and in which a defendant that is a corporation is subject to personal jurisdiction at the time an action is commenced, such corporation shall be deemed to reside in any district in that State within which its contacts would be sufficient to subject it to personal jurisdiction if that district were a separate State, and, if there is no such district, the corporation shall be deemed to reside in the district within which it has the most significant contacts."],[0,"(e) Actions Where Defendant Is Officer or Employee of the United States.—"],[1,"(1) In general.—A civil action in which a defendant is an officer or employee of the United States or any agency thereof acting in his official capacity or under color of legal authority, or an agency of the United States, or the United States, may, except as otherwise provided by law, be brought in any judicial district in which (A) a defendant in the action resides, (B) a substantial part of the events or omissions giving rise to the claim occurred, or a substantial part of property that is the subject of the action is situated, or (C) the plaintiff resides if no real property is involved in the action. Additional persons may be joined as parties to any such action in accordance with the Federal Rules of Civil Procedure and with such other venue requirements as would be applicable if the United States or one of its officers, employees, or agencies were not a party."],[1,"(2) Service.—The summons and complaint in such an action shall be served as provided by the Federal Rules of Civil Procedure except that the delivery of the summons and complaint to the officer or agency as required by the rules may be made by certified mail beyond the territorial limits of the district in which the action is brought."],[0,"(f) Civil Actions Against a Foreign State.—A civil action against a foreign state as defined in section 1603(a) of this title may be brought—"],[1,"(1) in any judicial district in which a substantial part of the events or omissions giving rise to the claim occurred, or a substantial part of property that is the subject of the action is situated;"],[1,"(2) in any judicial district in which the vessel or cargo of a foreign state is situated, if the claim is asserted under section 1605(b) of this title;"],[1,"(3) in any judicial district in which the agency or instrumentality is licensed to do business or is doing business, if the action is brought against an agency or instrumentality of a foreign state as defined in section 1603(b) of this title; or"],[1,"(4) in the United States District Court for the District of Columbia if the action is brought against a foreign state or political subdivision thereof."],[0,"(g) Multiparty, Multiforum Litigation.—A civil action in which jurisdiction of the district court is based upon section 1369 of this title may be brought in any district in which any defendant resides or in which a substantial part of the accident giving rise to the action took place."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1391?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1391. Venue generally","tname":"Judiciary and Judicial Procedure","by":{"0":"33, 33","1":"41","2":"15, 16, 16, 17"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","by":{"0":"37"}},{"t":"usc","label":"29 U.S.C. § 210","url":"https://www.law.cornell.edu/uscode/text/29/210","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"29 U.S.C. § 660","url":"https://www.law.cornell.edu/uscode/text/29/660","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"31 U.S.C. § 3732","url":"https://www.law.cornell.edu/uscode/text/31/3732","subs":["(a)"],"by":{"0":"33"}},{"t":"usc","label":"33 U.S.C. § 921","url":"https://www.law.cornell.edu/uscode/text/33/921","subs":["(c)"],"stext":{"head":"§921. Review of compensation orders","paras":[[0,"(a) Effectiveness and finality of orders"],[0,"A compensation order shall become effective when filed in the office of the deputy commissioner as provided in section 919 of this title, and, unless proceedings for the suspension or setting aside of such order are instituted as provided in subsection (b) of this section, shall become final at the expiration of the thirtieth day thereafter."],[0,"(b) Benefits Review Board; establishment; members; chairman; quorum; voting; questions reviewable; record; conclusiveness of findings; stay of payments; remand"],[0,"(1) There is hereby established a Benefits Review Board which shall be composed of five members appointed by the Secretary from among individuals who are especially qualified to serve on such Board. The Secretary shall designate one of the members of the Board to serve as chairman. The Chairman shall have the authority, as delegated by the Secretary, to exercise all administrative functions necessary to operate the Board."],[0,"(2) For the purpose of carrying out its functions under this chapter, three members of the Board shall constitute a quorum and official action can be taken only on the affirmative vote of at least three members."],[0,"(3) The Board shall be authorized to hear and determine appeals raising a substantial question of law or fact taken by any party in interest from decisions with respect to claims of employees under this chapter and the extensions thereof. The Board's orders shall be based upon the hearing record. The findings of fact in the decision under review by the Board shall be conclusive if supported by substantial evidence in the record considered as a whole. The payment of the amounts required by an award shall not be stayed pending final decision in any such proceeding unless ordered by the Board. No stay shall be issued unless irreparable injury would otherwise ensue to the employer or carrier."],[0,"(4) The Board may, on its own motion or at the request of the Secretary, remand a case to the administrative law judge for further appropriate action. The consent of the parties in interest shall not be a prerequisite to a remand by the Board."],[0,"(5) Notwithstanding paragraphs (1) through (4), upon application of the Chairman of the Board, the Secretary may designate up to four Department of Labor administrative law judges to serve on the Board temporarily, for not more than one year. The Board is authorized to delegate to panels of three members any or all of the powers which the Board may exercise. Each such panel shall have no more than one temporary member. Two members shall constitute a quorum of a panel. Official adjudicative action may be taken only on the affirmative vote of at least two members of a panel. Any party aggrieved by a decision of a panel of the Board may, within thirty days after the date of entry of the decision, petition the entire permanent Board for review of the panel's decision. Upon affirmative vote of the majority of the permanent members of the Board, the petition shall be granted. The Board shall amend its Rules of Practice to conform with this paragraph. Temporary members, while serving as members of the Board, shall be compensated at the same rate of compensation as regular members."],[0,"(c) Court of appeals; jurisdiction; persons entitled to review; petition; record; determination and enforcement; service of process; stay of payments"],[0,"Any person adversely affected or aggrieved by a final order of the Board may obtain a review of that order in the United States court of appeals for the circuit in which the injury occurred, by filing in such court within sixty days following the issuance of such Board order a written petition praying that the order be modified or set aside. A copy of such petition shall be forthwith transmitted by the clerk of the court, to the Board, and to the other parties, and thereupon the Board shall file in the court the record in the proceedings as provided in section 2112 of title 28. Upon such filing, the court shall have jurisdiction of the proceeding and shall have the power to give a decree affirming, modifying, or setting aside, in whole or in part, the order of the Board and enforcing same to the extent that such order is affirmed or modified. The orders, writs, and processes of the court in such proceedings may run, be served, and be returnable anywhere in the United States. The payment of the amounts required by an award shall not be stayed pending final decision in any such proceeding unless ordered by the court. No stay shall be issued unless irreparable injury would otherwise ensue to the employer or carrier. The order of the court allowing any stay shall contain a specific finding, based upon evidence submitted to the court and identified by reference thereto, that irreparable damage would result to the employer, and specifying the nature of the damage."],[0,"(d) District court; jurisdiction; enforcement of orders; application of beneficiaries of awards or deputy commissioner; process for compliance with orders"],[0,"If any employer or his officers or agents fails to comply with a compensation order making an award, that has become final, any beneficiary of such award or the deputy commissioner making the order, may apply for the enforcement of the order to the Federal district court for the judicial district in which the injury occurred (or to the United States District Court for the District of Columbia if the injury occurred in the District). If the court determines that the order was made and served in accordance with law, and that such employer or his officers or agents have failed to comply therewith, the court shall enforce obedience to the order by writ of injunction or by other proper process, mandatory or otherwise, to enjoin upon such person and his officers and agents compliance with the order."],[0,"(e) Institution of proceedings for suspension, setting aside, or enforcement of compensation orders"],[0,"Proceedings for suspending, setting aside, or enforcing a compensation order, whether rejecting a claim or making an award, shall not be instituted otherwise than as provided in this section and section 918 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/921?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§921. Review of compensation orders","tname":"Navigation and Navigable Waters","by":{"0":"26"}},{"t":"usc","label":"43 U.S.C. § 1349","url":"https://www.law.cornell.edu/uscode/text/43/1349","subs":["(b)(1)"],"by":{"0":"33"}},{"t":"usc","label":"47 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/47/402","subs":["(b)(6)"],"by":{"0":"15"}},{"t":"usc","label":"49 U.S.C. § 5127","url":"https://www.law.cornell.edu/uscode/text/49/5127","subs":["(a)"],"by":{"0":"37"}},{"t":"usc","label":"49 U.S.C. § 44309","url":"https://www.law.cornell.edu/uscode/text/49/44309","subs":["(d)(1)"],"by":{"0":"33"}},{"t":"usc","label":"49 U.S.C. § 47106","url":"https://www.law.cornell.edu/uscode/text/49/47106","subs":["(d)(3)"],"by":{"0":"37"}},{"t":"usc","label":"49 U.S.C. § 47111","url":"https://www.law.cornell.edu/uscode/text/49/47111","subs":["(d)(3)"],"by":{"0":"37"}},{"t":"rule","label":"Fed. R. App. P. 15","url":"https://www.law.cornell.edu/rules/frap/rule_15","subs":["(a)(1)"],"by":{"0":"29","1":"42, 45"}},{"t":"rule","label":"Fed. R. Civ. P. 20","url":"https://www.law.cornell.edu/rules/frcp/rule_20","subs":["(a)(1)"],"by":{"0":"29"}},{"t":"case","label":"ACLU v. Clapper","cite":"785 F.3d 787","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/785/787/","by":{"1":"35"}},{"t":"case","label":"Am. Constr. Co. v. Jacksonville, Tampa & Key W. Ry. Co.","cite":"148 U.S. 372","y":1893,"id":"scdb/1892-154","sc":1,"sum":"A writ of mandamus does not lie to the United States Circuit Court of Appeals to review, or to the Circuit Court of the United States to disregard, a decree of the Circuit Cour$ of Appeals, made on appeal from an interlocutory order of the Circuit'Court, and alleged to be in excess of its powers on such an appeal, but which might be made on appeal from the final decree, when rendered.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"Am. Dredging Co. v. Miller","cite":"510 U.S. 443","y":1994,"id":"1993/91-1950","sc":1,"sum":"The Court decided that \"forum non conveniens\" claims were only procedural, not substantive, and that national uniformity was therefore not required by the Constitution. Writing for the seven-member majority, Justice Antonin Scalia stated \"venue is a matter that goes to process rather than substantive rights -- determining which among various competent courts will decide the case.","sumSrc":"Oyez","by":{"1":"11, 42"}},{"t":"case","label":"Am. Power & Light Co. v. SEC","cite":"325 U.S. 385","y":1945,"id":"scdb/1944-033","sc":1,"sum":"1. Under § 24 (a) of the Public Utility Holding Company Act, which grants a right of review to \"any person or party aggrieved\" by an order issued by the Securities & Exchange Commission under the Act, a stockholder having a substantial financial or economic interest distinct from that of the corporation, which is directly and adversely affected by an order of the Commission, is a \"person aggrieved.\"","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Anglo Canadian Shipping Co. v. United States","cite":"238 F.2d 18","y":1956,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/238/18/","by":{"1":"41"}},{"t":"case","label":"Ass’n of Data Processing Serv. Orgs., Inc. v. Camp","cite":"397 U.S. 150","y":1970,"id":"1969/85","sc":1,"op":3,"sum":"Petitioners, which provide data processing services to businesses generally, challenge a ruling by the Comptroller of the Currency permitting national banks, such as respondent bank, as an incident to their banking services, to make data processing services available to other banks and bank customers. The District Court dismissed the complaint, holding that petitioners lacked standing to bring the suit, and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Bank of Am. v. City of Miami","cite":"581 U.S. 189","y":2015,"id":"2016/15-1111","sc":1,"op":4,"sum":"The Court determined that the “aggrieved persons” language of the Fair Housing Act (FHA) does not impose a more narrow standing standard than Article III does and allows a city to sue, but the proximate cause standard requires the plaintiffs to show more than the possibility that a defendant could have foreseen the harm.","sumSrc":"Oyez","by":{"1":"10, 19, 21, 22, 23, 24","2":"6"}},{"t":"case","label":"Bragdon v. Abbott","cite":"524 U.S. 624","y":1998,"id":"1997/97-156","sc":1,"ar":1,"sum":"In a 5-to-4 opinion, the Court held that although the ADA does not force care-givers to treat an \"individual [who] poses a direct threat to the health or safety of others,\" it also prohibits discrimination against any individual \"on the basis of disability in the enjoyment of the services of any place of public accommodation by any person who operates [such] a place.\" The Court then reasoned that since HIV \"substantially limits\" major life activities, such as reproduction, the infection is a \"disability\" that entitles its victims to ADA protections.","sumSrc":"Oyez","by":{"1":"3, 42"}},{"t":"case","label":"Burlington Northern, Inc. v. United States","cite":"549 F.2d 83","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/549/83/","by":{"1":"41"}},{"t":"case","label":"Calumet Indus., Inc. v. Brock","cite":"807 F.2d 225","y":1986,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/807/225/","by":{"1":"27, 28"}},{"t":"case","label":"Cheney v. U.S. Dist. Ct.","cite":"542 U.S. 367","y":2004,"id":"2003/03-475","sc":1,"sum":"The Court sent the case back to the D.C. Court of Appeals, arguing that the appellate court should have considered separation-of-powers claims and was wrong to conclude it lacked authority to order District Court discovery to stop.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Citizens to Preserve Overton Park, Inc. v. Volpe","cite":"401 U.S. 402","y":1971,"id":"1970/1066","sc":1,"sum":"Under § 4 (f) of the Department. of Transportation Act of 1966 and § 138 of the Federal-Aid Highway Act of 1968, the Secretary of Transportation may not authorize use of federal funds to finance construction of highways through public parks if a \"feasible and prudent\" alternative route exists. If no such route is available, he may approve construction only if there has been \"all possible planning to minimize harm\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Clarke v. Sec. Indus. Ass’n","cite":"479 U.S. 388","y":1987,"id":"1986/85-971","sc":1,"op":6,"sum":"Petitioner Security Pacific National Bank (Security Pacific) applied to the Comptroller of the Currency for permission to establish an affiliate named Discount Brokerage, and to offer discount brokerage services not only at its branch offices but also at other locations inside and outside of its home State. A pertinent branching provision of the National Bank Act, 12 U. S. C. § 81, originally enacted in 1927 as part …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 23, 29","2":"10"}},{"t":"case","label":"Clinton v. City of New York","cite":"524 U.S. 417","y":1998,"id":"1997/97-1374","sc":1,"sum":"A case in which the Court declared that pieces of legislation passed by both houses of Congress must be either passed or vetoed as a whole, not in separate parts.","sumSrc":"Oyez","by":{"1":"20","2":"8"}},{"t":"case","label":"Cohen v. Beneficial Loan Co.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Coleman v. Paccar Inc.","cite":"424 U.S. 1301","y":1976,"url":"https://supreme.justia.com/cases/federal/us/424/1301/","sc":1,"sum":"Noting that Congress has not enacted a “provision for appeal eo nomine from an interlocutory order of a court of appeals”.","sumSrc":"brief:1","by":{"1":"17"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Dart Cherokee Basin Op. Co. v. Owens","cite":"574 U.S. 81","y":2014,"id":"2014/13-719","sc":1,"sum":"The Court ruled that a defendant seeking removal of a case to federal court is not required to provide evidence supporting federal jurisdiction in the notice of removal.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Degge v. Hitchcock","cite":"229 U.S. 162","y":1913,"id":"scdb/1912-222","sc":1,"sum":"This is apparently the first case in which a Federal court has been asked to issue a writ of certiorari to review a ruling by an executive officer of the United States Government.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Esposito v. Home Depot, USA, Inc.","cite":"436 F. Supp. 2d 343","y":2006,"court":"D.R.I.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/436/343/","by":{"1":"48"}},{"t":"case","label":"Est. of Israel v. Comm’r","cite":"159 F.3d 593","y":1998,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/159/593/","by":{"1":"41","2":"18"}},{"t":"case","label":"Exxon Corp. v. FTC","cite":"588 F.2d 895","y":1978,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/588/895/","by":{"1":"44","2":"16, 17"}},{"t":"case","label":"Favereau v. United States","cite":"44 F. Supp. 2d 68","y":1999,"court":"D. Me.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/44/68/","sum":"Noting that “only” changes the venue calculus.","sumSrc":"brief:1","by":{"1":"46"}},{"t":"case","label":"FCC v. Nat’l Broad. Co.","cite":"319 U.S. 239","y":1943,"id":"scdb/1942-060","sc":1,"sum":"1. The proprietor of a broadcasting station whose license from the Federal Communications Commission entitles him to employ a specified frequency and a specified power and assigns to him a clear channel at night free from electrical interference is entitled under § 312 (b) of the Federal Communications Commission Act to be made a party to a proceeding before the Commission looking to the granting of an application …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Flemming v. Fla. Citrus Exch.","cite":"358 U.S. 153","y":1958,"id":"1958/27","sc":1,"ar":1,"sum":"The Secretary's order -was lawful, and the judgment is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Fournier v. Johnson","cite":"677 F. Supp. 2d 1172","y":2009,"court":"D. Ariz.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/677/1172/","by":{"1":"41"}},{"t":"case","label":"Global Van Lines, Inc. v. ICC","cite":"691 F.2d 773","y":1982,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/691/773/","by":{"1":"41"}},{"t":"case","label":"Goodyear Atomic Corp. v. Miller","cite":"486 U.S. 174","y":1988,"id":"1987/86-1172","sc":1,"sum":"Appellee Miller, an employee of appellant at an Ohio nuclear production facility owned by the United States but operated by appellant, a private contractor, received a workers' compensation award from appellee Ohio Industrial Commission (Commission) for injuries sustained in a fall allegedly caused by a bolt protruding from the scaffold on which he was working. On the basis of a state safety regulation prohibiting …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Harrison v. PPG Indus., Inc.","cite":"446 U.S. 578","y":1980,"id":"1979/78-1918","sc":1,"sum":"The phrase \"any other final action\" in § 307 (b) (1) is to be construed in accordance with its literal meaning so as to reach any action of the Administrator that is final, not just final actions of the Administrator similar to actions under the specifically enumerated provisions that precede the catchall phrase in the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"48"}},{"t":"case","label":"Hohn v. United States","cite":"524 U.S. 236","y":1998,"id":"1997/96-8986","sc":1,"sum":"This decision overrules that portion of House v. Mayo, 324 U.S. 42, 44 (1945) (per curiam), which held that the Court lacks statutory certiorari jurisdiction to review denials of certificates of probable cause.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"International Union v. Scofield","cite":"382 U.S. 205","y":1965,"id":"1965/18","sc":1,"sum":"In No. 18, a union was charged by individual employees with violations of the National Labor Relations Act, and the Board's General Counsel issued a complaint. The NLRB dismissed the complaint after a hearing and the individual employees sought review in the Court of Appeals. The NLRB filed an answer supporting the decision. A motion of intervention filed by the union, although not opposed by the NLRB or the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Jama v. ICE","cite":"543 U.S. 335","y":2005,"id":"2004/03-674","sc":1,"sum":"Federal immigration law permitted an alien to be removed to a country without the advance consent of that country's government. Of the four removal options federal immigration law listed, an acceptance requirement appeared in only one clause: \"...he shall be removed to another country whose government will accept him.\" That clause only applied after the attorney general attempted the prior deportation option.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Lauro Lines s.r.l. v. Chasser","cite":"490 U.S. 495","y":1989,"id":"1988/88-23","sc":1,"sum":"An interlocutory order denying a defendant's motion to dismiss a damages action on the basis of a contractual forum-selection clause is not immediately appealable under § 1291. Such an order is not final in the usual sense, for it does not end the litigation on the merits but, on the contrary, ensures that the litigation will continue. Nor does the order fall within the narrow exception to the normal application of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12, 16"}},{"t":"case","label":"Major League Baseball Players Ass’n v. Garvey","cite":"532 U.S. 504","y":2001,"id":"2000/00-1210","sc":1,"sum":"The Court reversed the Court of Appeals' determination because it conflicted with the Court's cases limiting review of an arbitrator's award entered pursuant to an agreement between an employer and a labor organization and prescribing the appropriate remedy where vacation of the award is warranted.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Match-E-Be-Nash-She-Wish Band of Pottawatomi Indians v. Patchak","cite":"567 U.S. 209","y":2012,"id":"2011/11-246","sc":1,"sum":"The Court held that a neighbor of a proposed Indian casino had standing to sue the government for taking 147 acres of a town's land under Section 465 of the Indian Reorganization Act.","sumSrc":"Oyez","by":{"1":"19, 23"}},{"t":"case","label":"McManus v. Glassman’s Wynnefield, Inc.","cite":"710 F. Supp. 1043","y":1989,"court":"E.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./710/1043/","by":{"1":"48"}},{"t":"case","label":"Mohamad v. Palestinian Auth.","cite":"566 U.S. 449","y":2012,"id":"2011/11-88","sc":1,"sum":"The Court held that the word \"individual\" in the Torture Victim Protection Act means a natural person and does not impose any liability against organizations.","sumSrc":"Oyez","by":{"1":"25"}},{"t":"case","label":"Nat’l Ass’n of Priv. Fund Managers v. SEC","cite":"103 F.4th 1097","y":2024,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/103/1097/","by":{"1":"41","2":"18"}},{"t":"case","label":"NFIB v. Dep’t of Labor","cite":"595 U.S. 109","y":2022,"url":"https://supreme.justia.com/cases/federal/us/595/109/","sc":1,"by":{"1":"15"}},{"t":"case","label":"OBB Personenverkehr AG v. Sachs","cite":"577 U.S. 27","y":2015,"id":"2015/13-1067","sc":1,"op":1,"sum":"The Court held that the commercial activity exception to the Foreign Sovereign Immunity Act only applies when the suit is based upon activity that took place in the United States, and it was not sufficient to establish a single element of the claim in question.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Ortiz v. United States","cite":"585 U.S. 427","y":2018,"id":"2017/16-1423","sc":1,"sum":"The Court held that it has jurisdiction to review the CAAF's decisions and that Judge Martin T. Mitchell’s simultaneous service on the US Court of Military Commission Review (CMCR) and the US Air Force Court of Criminal Appeals (AFCCA) does not violate the Appointments Clause or 10 U.S.C. § 973(b)(2)(A).","sumSrc":"Oyez","by":{"1":"12, 14"}},{"t":"case","label":"Quarles v. Gen’l Inv. & Dev. Co.","cite":"260 F. Supp. 2d 1","y":2003,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/260/1/","by":{"1":"44"}},{"t":"case","label":"Radio Relay Corp. v. FCC","cite":"409 F.2d 322","y":1969,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/409/322/","by":{"1":"41"}},{"t":"case","label":"Ry. Labor Execs.’ Ass’n v. Interstate Com. Comm’n","cite":"958 F.2d 252","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/958/252/","by":{"1":"44"}},{"t":"case","label":"SAS Inst. Inc. v. Iancu","cite":"584 U.S. 357","y":2018,"id":"2017/16-969","sc":1,"sum":"The Court decided that when the United States Patent and Trademark Office institutes an inter partes review to reconsider an already-issued patent claim, under 35 U.S.C. §§ 311-319, it must decide the patentability of all of the claims the petitioner has challenged.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Sidney Coal Co. v. Soc. Sec. Admin.","cite":"427 F.3d 336","y":2005,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/427/336/","ar":1,"by":{"1":"41, 44, 47","2":"16"}},{"t":"case","label":"Simmons v. ICC","cite":"716 F.2d 40","y":1983,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/716/40/","by":{"1":"26"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Env’t","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"15, 16"}},{"t":"case","label":"Stringfellow v. Concerned Neighbors in Action","cite":"480 U.S. 370","y":1987,"id":"1986/85-184","sc":1,"sum":"A district court order granting permissive intervention but denying intervention as of right is not immediately appealable. Such an order is not \"final\" in the traditional sense since it does not end the litigation. Furthermore, it does not fall within one of the narrow categories the Court has deemed final for review purposes.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Texas Dep’t of Hous. & Cmty. Affs. v. Inclusive Cmtys. Project, Inc.","cite":"576 U.S. 519","y":2015,"id":"2014/13-1371","sc":1,"sum":"The Court determined that evidence of disparate impact is sufficient to allege a claim that the defendant violated the Fair Housing Act.","sumSrc":"Oyez","by":{"1":"11, 40"}},{"t":"case","label":"Texas v. EPA","cite":"829 F.3d 405","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/829/405/","by":{"1":"48"}},{"t":"case","label":"United States v. Nixon","cite":"418 U.S. 683","y":1974,"id":"1973/73-1766","sc":1,"sum":"The Court held that the President does not have executive privilege in immunity from subpoenas or other civil court actions.","sumSrc":"Oyez","by":{"1":"13, 14"}},{"t":"case","label":"Verizon Md. Inc. v. Public Serv. Comm’n of Md.","cite":"535 U.S. 635","y":2002,"id":"2001/00-1531","sc":1,"sum":"The Court held that the district court had jurisdiction, so as to review the Commission's order for compliance with federal law, to entertain the suit because resolution of the LEC's claim turned on whether the Act, or an FCC ruling issued thereunder, precluded the state commission from ordering payment of reciprocal compensation.","sumSrc":"Oyez","by":{"1":"14"}},{"t":"case","label":"Wages & White Lion Invs., L.L.C. v. FDA","cite":"16 F.4th 1130","y":2021,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/16/1130/","by":{"1":"5"}},{"t":"case","label":"Wheeler Lumber Bridge & Supply Co. v. United States","cite":"281 U.S. 572","y":1930,"id":"scdb/1929-102","sc":1,"by":{"1":"14, 15"}},{"t":"case","label":"White v. Turk","cite":"37 U.S. 238","y":1838,"id":"scdb/1838-039","sc":1,"sum":"The intention of congress, in passing the act, authorizing a division of opinion of the judges of the circuit courts of the United States to be certified to the Supreme Court was, that a division of the judges of the circuit. court, upon a single and material point, in the progress of the cause,.should be certified to the Supreme Court for its opinion; and not the whole cause. When a.certificate of division brings …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Whole Women’s Health v. Jackson","cite":"595 U.S. 30","y":2021,"id":"2021/21-463","sc":1,"sum":"A pre-enforcement challenge under the Federal Constitution to Texas Senate Bill 8—the Texas Heartbeat Act—may proceed past the motion to dismiss stage against certain of the named defendants but not others; the order of the District Court is affirmed in part and reversed in part, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"13, 14"}},{"t":"usc","label":"7 U.S.C. § 228b-3","url":"https://www.law.cornell.edu/uscode/text/7/228b-3","by":{"1":"26"}},{"t":"usc","label":"7 U.S.C. § 608c","url":"https://www.law.cornell.edu/uscode/text/7/608c","stext":{"head":"§608c. Orders","paras":[[0,"(1) Issuance by Secretary"],[0,"The Secretary of Agriculture shall, subject to the provisions of this section, issue, and from time to time amend, orders applicable to processors, associations of producers, and others engaged in the handling of any agricultural commodity or product thereof specified in subsection (2) of this section. Such persons are referred to in this chapter as \"handlers\". Such orders shall regulate, in the manner hereinafter in this section provided, only such handling of such agricultural commodity, or product thereof, as is in the current of interstate or foreign commerce, or which directly burdens, obstructs, or affects, interstate or foreign commerce in such commodity or product thereof. In carrying out this section, the Secretary shall complete all informal rulemaking actions necessary to respond to recommendations submitted by administrative committees for such orders as expeditiously as possible, but not more than 45 days (to the extent practicable) after submission of the committee recommendations. The Secretary is authorized to implement a producer allotment program and a handler withholding program under the cranberry marketing order in the same crop year through informal rulemaking based on a recommendation and supporting economic analysis submitted by the Cranberry Marketing Committee. Such recommendation and analysis shall be submitted by the Committee no later than March 1 of each year. The Secretary shall establish time frames for each office and agency within the Department of Agriculture to consider the committee recommendations."],[0,"(2) Commodities to which applicable"],[0,"Orders issued pursuant to this section shall be applicable only to (A) the following agricultural commodities and the products thereof (except canned or frozen pears, grapefruit, cherries, apples, or cranberries, the products of naval stores, and the products of honeybees), or to any regional, or market classification of any such commodity or product: Milk, fruits (including filberts, almonds, pecans and walnuts but not including apples, other than apples produced in the States of Washington, Oregon, Idaho, New York, Michigan, Maryland, New Jersey, Indiana, California, Maine, Vermont, New Hampshire, Rhode Island, Massachusetts, Connecticut, Colorado, Utah, New Mexico, Illinois, and Ohio, and not including fruits for canning or freezing other than pears, olives, grapefruit, cherries, caneberries (including raspberries, blackberries, and loganberries), cranberries, and apples produced in the States named above except Washington, Oregon, and Idaho), tobacco, vegetables (not including vegetables, other than asparagus, for canning or freezing and not including potatoes for canning, freezing, or other processing), hops, honeybees and naval stores as included in the Naval Stores Act [7 U.S.C. 91 et seq.] and standards established thereunder (including refined or partially refined oleoresin): Provided, That no order issued pursuant to this section shall be effective as to any grapefruit for canning or freezing unless the Secretary of Agriculture determines, in addition to other findings and determinations required by this chapter, that the issuance of such order is approved or favored by the processors who, during a representative period determined by the Secretary, have been engaged in canning or freezing such commodity for market and have canned or frozen for market more than 50 per centum of the total volume of such commodity canned or frozen for market during such representative period; and (B) any agricultural commodity (except honey, cotton, rice, wheat, corn, grain sorghums, oats, barley, rye, sugarcane, sugarbeets, wool, mohair, livestock, soybeans, cottonseed, flaxseed, poultry (but not excepting turkeys and not excepting poultry which produce commercial eggs), fruits and vegetables for canning or freezing, including potatoes for canning, freezing, or other processing 1 and apples), or any regional or market classification thereof, not subject to orders under (A) of this subdivision, but not the products (including canned or frozen commodities or products) thereof. No order issued pursuant to this section shall be effective as to cherries, apples, or cranberries for canning or freezing unless the Secretary of Agriculture determines, in addition to other required findings and determinations, that the issuance of such order is approved or favored by processors who, during a representative period determined by the Secretary, have engaged in canning or freezing such commodity for market and have frozen or canned more than 50 per centum of the total volume of the commodity to be regulated which was canned or frozen within the production area, or marketed within the marketing area, defined in such order, during such representative period. No order issued pursuant to this section shall be applicable to peanuts produced in more than one of the following production areas: the Virginia-Carolina production area, the Southeast production area, and the Southwest production area. If the Secretary determines that the declared policy of this chapter will be better achieved thereby (i) the commodities of the same general class and used wholly or in part for the same purposes may be combined and treated as a single commodity and (ii) the portion of an agricultural commodity devoted to or marketed for a particular use or combination of uses, may be treated as a separate agricultural commodity. All agricultural commodities and products covered hereby shall be deemed specified herein for the purposes of subsections (6) and (7)."],[0,"(3) Notice and hearing"],[0,"Whenever the Secretary of Agriculture has reason to believe that the issuance of an order will tend to effectuate the declared policy of this chapter with respect to any commodity or product thereof specified in subsection (2) of this section, he shall give due notice of and an opportunity for a hearing upon a proposed order."],[0,"(4) Finding and issuance of order"],[0,"After such notice and opportunity for hearing, the Secretary of Agriculture shall issue an order if he finds, and sets forth in such order, upon the evidence introduced at such hearing (in addition to such other findings as may be specifically required by this section) that the issuance of such order and all of the terms and conditions thereof will tend to effectuate the declared policy of this chapter with respect to such commodity."],[0,"(5) Terms—Milk and its products"],[0,"In the case of milk and its products, orders issued pursuant to this section shall contain one or more of the following terms and conditions, and (except as provided in subsection (7)) no others:"],[0,"(A) Classifying milk in accordance with the form in which or the purpose for which it is used, and fixing, or providing a method for fixing, minimum prices for each such use classification which all handlers shall pay, and the time when payments shall be made, for milk purchased from producers or associations of producers. Such prices shall be uniform as to all handlers, subject only to adjustments for (1) volume, market, and production differentials customarily applied by the handlers subject to such order, (2) the grade or quality of the milk purchased, and (3) the locations at which delivery of such milk, or any use classification thereof, is made to such handlers. Throughout the 2-year period beginning on the effective date of this sentence (and subsequent to such 2-year period unless modified by amendment to the order involved), for purposes of determining prices for milk of the highest use classification, the Class I skim milk price per hundredweight specified in section 1000.50(b) of title 7, Code of Federal Regulations (or successor regulations), shall be the sum of the adjusted Class I differential specified in section 1000.52 of such title 7 (or successor regulations), plus the adjustment to Class I prices specified in sections 1005.51(b), 1006.51(b), and 1007.51(b) of such title 7 (or successor regulations), plus the simple average of the advanced pricing factors computed in sections 1000.50(q)(1) and 1000.50(q)(2) of such title 7 (or successor regulations), plus $0.74."],[0,"(B) Providing:"],[1,"(i) for the payment to all producers and associations of producers delivering milk to the same handler of uniform prices for all milk delivered by them: Provided, That, except in the case of orders covering milk products only, such provision is approved or favored by at least three-fourths of the producers who, during a representative period determined by the Secretary of Agriculture, have been engaged in the production for market of milk covered in such order or by producers who, during such representative period, have produced at least three-fourths of the volume of such milk produced for market during such period; the approval required hereunder shall be separate and apart from any other approval or disapproval provided for by this section; or"],[1,"(ii) for the payment to all producers and associations of producers delivering milk to all handlers of uniform prices for all milk so delivered, irrespective of the uses made of such milk by the individual handler to whom it is delivered;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/7/608c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§608c. Orders","tname":"Agriculture","by":{"1":"34, 35"}},{"t":"usc","label":"8 U.S.C. § 1189","url":"https://www.law.cornell.edu/uscode/text/8/1189","by":{"1":"26, 27"}},{"t":"usc","label":"10 U.S.C. § 1508","url":"https://www.law.cornell.edu/uscode/text/10/1508","by":{"1":"27"}},{"t":"usc","label":"12 U.S.C. § 4634","url":"https://www.law.cornell.edu/uscode/text/12/4634","by":{"1":"26"}},{"t":"usc","label":"15 U.S.C. § 298","url":"https://www.law.cornell.edu/uscode/text/15/298","by":{"1":"27"}},{"t":"usc","label":"15 U.S.C. § 1333","url":"https://www.law.cornell.edu/uscode/text/15/1333","subs":["(b)"],"stext":{"head":"§1333. Labeling","paras":[[0,"(a) Label requirements"],[0,"(1) In general"],[1,"It shall be unlawful for any person to manufacture, package, sell, offer to sell, distribute, or import for sale or distribution within the United States any cigarettes the package of which fails to bear, in accordance with the requirements of this section, one of the following labels:"],[2,"WARNING: Cigarettes are addictive."],[2,"WARNING: Tobacco smoke can harm your children."],[2,"WARNING: Cigarettes cause fatal lung disease."],[2,"WARNING: Cigarettes cause cancer."],[2,"WARNING: Cigarettes cause strokes and heart disease."],[2,"WARNING: Smoking during pregnancy can harm your baby."],[2,"WARNING: Smoking can kill you."],[2,"WARNING: Tobacco smoke causes fatal lung disease in nonsmokers."],[2,"WARNING: Quitting smoking now greatly reduces serious risks to your health."],[0,"(2) Placement; typography; etc."],[1,"Each label statement required by paragraph (1) shall be located in the upper portion of the front and rear panels of the package, directly on the package underneath the cellophane or other clear wrapping. Each label statement shall comprise the top 50 percent of the front and rear panels of the package. The word \"WARNING\" shall appear in capital letters and all text shall be in conspicuous and legible 17-point type, unless the text of the label statement would occupy more than 70 percent of such area, in which case the text may be in a smaller conspicuous and legible type size, provided that at least 60 percent of such area is occupied by required text. The text shall be black on a white background, or white on a black background, in a manner that contrasts, by typography, layout, or color, with all other printed material on the package, in an alternating fashion under the plan submitted under subsection (c)."],[0,"(3) Does not apply to foreign distribution"],[1,"The provisions of this subsection do not apply to a tobacco product manufacturer or distributor of cigarettes which does not manufacture, package, or import cigarettes for sale or distribution within the United States."],[0,"(4) Applicability to retailers"],[1,"A retailer of cigarettes shall not be in violation of this subsection for packaging that—"],[2,"(A) contains a warning label;"],[2,"(B) is supplied to the retailer by a license- or permit-holding tobacco product manufacturer, importer, or distributor; and"],[2,"(C) is not altered by the retailer in a way that is material to the requirements of this subsection."],[0,"(b) Advertising requirements"],[0,"(1) In general"],[1,"It shall be unlawful for any tobacco product manufacturer, importer, distributor, or retailer of cigarettes to advertise or cause to be advertised within the United States any cigarette unless its advertising bears, in accordance with the requirements of this section, one of the labels specified in subsection (a)."],[0,"(2) Typography, etc."],[1,"Each label statement required by subsection (a) in cigarette advertising shall comply with the standards set forth in this paragraph. For press and poster advertisements, each such statement and (where applicable) any required statement relating to tar, nicotine, or other constituent (including a smoke constituent) yield shall comprise at least 20 percent of the area of the advertisement and shall appear in a conspicuous and prominent format and location at the top of each advertisement within the trim area. The Secretary may revise the required type sizes in such area in such manner as the Secretary determines appropriate. The word \"WARNING\" shall appear in capital letters, and each label statement shall appear in conspicuous and legible type. The text of the label statement shall be black if the background is white and white if the background is black, under the plan submitted under subsection (c). The label statements shall be enclosed by a rectangular border that is the same color as the letters of the statements and that is the width of the first downstroke of the capital \"W\" of the word \"WARNING\" in the label statements. The text of such label statements shall be in a typeface pro rata to the following requirements: 45-point type for a whole-page broadsheet newspaper advertisement; 39-point type for a half-page broadsheet newspaper advertisement; 39-point type for a whole-page tabloid newspaper advertisement; 27-point type for a half-page tabloid newspaper advertisement; 31.5-point type for a double page spread magazine or whole-page magazine advertisement; 22.5-point type for a 28 centimeter by 3 column advertisement; and 15-point type for a 20 centimeter by 2 column advertisement. The label statements shall be in English, except that—"],[2,"(A) in the case of an advertisement that appears in a newspaper, magazine, periodical, or other publication that is not in English, the statements shall appear in the predominant language of the publication; and"],[2,"(B) in the case of any other advertisement that is not in English, the statements shall appear in the same language as that principally used in the advertisement."],[0,"(3) Matchbooks"],[1,"Notwithstanding paragraph (2), for matchbooks (defined as containing not more than 20 matches) customarily given away with the purchase of tobacco products, each label statement required by subsection (a) may be printed on the inside cover of the matchbook."],[0,"(4) Adjustment by Secretary"],[1,"The Secretary may, through a rulemaking under section 553 of title 5, adjust the format and type sizes for the label statements required by this section; the text, format, and type sizes of any required tar, nicotine yield, or other constituent (including smoke constituent) disclosures; or the text, format, and type sizes for any other disclosures required under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.]. The text of any such label statements or disclosures shall be required to appear only within the 20 percent area of cigarette advertisements provided by paragraph (2). The Secretary shall promulgate regulations which provide for adjustments in the format and type sizes of any text required to appear in such area to ensure that the total text required to appear by law will fit within such area."],[0,"(c) Marketing requirements"],[0,"(1) Random display"],[1,"The label statements specified in subsection (a)(1) shall be randomly displayed in each 12-month period, in as equal a number of times as is possible on each brand of the product and be randomly distributed in all areas of the United States in which the product is marketed in accordance with a plan submitted by the tobacco product manufacturer, importer, distributor, or retailer and approved by the Secretary."],[0,"(2) Rotation"],[1,"The label statements specified in subsection (a)(1) shall be rotated quarterly in alternating sequence in advertisements for each brand of cigarettes in accordance with a plan submitted by the tobacco product manufacturer, importer, distributor, or retailer to, and approved by, the Secretary."],[0,"(3) Review"],[1,"The Secretary shall review each plan submitted under paragraph (2) and approve it if the plan—"],[2,"(A) will provide for the equal distribution and display on packaging and the rotation required in advertising under this subsection; and"],[2,"(B) assures that all of the labels required under this section will be displayed by the tobacco product manufacturer, importer, distributor, or retailer at the same time."],[0,"(4) Applicability to retailers"],[1,"This subsection and subsection (b) apply to a retailer only if that retailer is responsible for or directs the label statements required under this section except that this paragraph shall not relieve a retailer of liability if the retailer displays, in a location open to the public, an advertisement that does not contain a warning label or has been altered by the retailer in a way that is material to the requirements of this subsection and subsection (b)."],[0,"(d) 1 Graphic label statements"],[0,"Not later than 24 months after June 22, 2009, the Secretary shall issue regulations that require color graphics depicting the negative health consequences of smoking to accompany the label statements specified in subsection (a)(1). The Secretary may adjust the type size, text and format of the label statements specified in subsections (a)(2) and (b)(2) as the Secretary determines appropriate so that both the graphics and the accompanying label statements are clear, conspicuous, legible and appear within the specified area."],[0,"(d) 1 Change in required statements"],[0,"The Secretary through a rulemaking conducted under section 553 of title 5 may adjust the format, type size, color graphics, and text of any of the label requirements, or establish the format, type size, and text of any other disclosures required under the Federal Food, Drug, and Cosmetic Act [21 U.S.C. 301 et seq.], if the Secretary finds that such a change would promote greater public understanding of the risks associated with the use of tobacco products."],[0,"(e) Tar, nicotine, and other smoke constituent disclosure"],[0,"(1) In general"],[1,"The Secretary shall, by a rulemaking conducted under section 553 of title 5, determine (in the Secretary's sole discretion) whether cigarette and other tobacco product manufacturers shall be required to include in the area of each cigarette advertisement specified by subsection (b) of this section, or on the package label, or both, the tar and nicotine yields of the advertised or packaged brand. Any such disclosure shall be in accordance with the methodology established under such regulations, shall conform to the type size requirements of subsection (b) of this section, and shall appear within the area specified in subsection (b) of this section."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/1333?type=usc&year=mostrecent&link-type=html"},"head":"§1333. Labeling","tname":"Commerce and Trade","by":{"1":"28, 29","2":"9"}},{"t":"usc","label":"21 U.S.C. § 1047","url":"https://www.law.cornell.edu/uscode/text/21/1047","by":{"1":"26"}},{"t":"usc","label":"21 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/21/2344","by":{"1":"26"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"1":"2, 9, 12, 14, 17, 18","2":"3, 4, 2, 3"}},{"t":"usc","label":"28 U.S.C. § 1651","url":"https://www.law.cornell.edu/uscode/text/28/1651","by":{"1":"17"}},{"t":"usc","label":"28 U.S.C. § 2101","url":"https://www.law.cornell.edu/uscode/text/28/2101","by":{"1":"15"}},{"t":"usc","label":"28 U.S.C. § 2112","url":"https://www.law.cornell.edu/uscode/text/28/2112","subs":["(a)","(a)(5)"],"by":{"1":"44, 45, 46","2":"20, 20, 21"}},{"t":"usc","label":"28 U.S.C. § 2343","url":"https://www.law.cornell.edu/uscode/text/28/2343","by":{"1":"40","2":"15, 16"}},{"t":"usc","label":"29 U.S.C. § 3247","url":"https://www.law.cornell.edu/uscode/text/29/3247","by":{"1":"26"}},{"t":"usc","label":"31 U.S.C. § 7107","url":"https://www.law.cornell.edu/uscode/text/31/7107","by":{"1":"27"}},{"t":"usc","label":"41 U.S.C. § 1327","url":"https://www.law.cornell.edu/uscode/text/41/1327","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 3613","url":"https://www.law.cornell.edu/uscode/text/42/3613","subs":["(a)"],"stext":{"head":"§3613. Enforcement by private persons","paras":[[0,"(a) Civil action"],[0,"(1)(A) An aggrieved person may commence a civil action in an appropriate United States district court or State court not later than 2 years after the occurrence or the termination of an alleged discriminatory housing practice, or the breach of a conciliation agreement entered into under this subchapter, whichever occurs last, to obtain appropriate relief with respect to such discriminatory housing practice or breach."],[0,"(B) The computation of such 2-year period shall not include any time during which an administrative proceeding under this subchapter was pending with respect to a complaint or charge under this subchapter based upon such discriminatory housing practice. This subparagraph does not apply to actions arising from a breach of a conciliation agreement."],[0,"(2) An aggrieved person may commence a civil action under this subsection whether or not a complaint has been filed under section 3610(a) of this title and without regard to the status of any such complaint, but if the Secretary or a State or local agency has obtained a conciliation agreement with the consent of an aggrieved person, no action may be filed under this subsection by such aggrieved person with respect to the alleged discriminatory housing practice which forms the basis for such complaint except for the purpose of enforcing the terms of such an agreement."],[0,"(3) An aggrieved person may not commence a civil action under this subsection with respect to an alleged discriminatory housing practice which forms the basis of a charge issued by the Secretary if an administrative law judge has commenced a hearing on the record under this subchapter with respect to such charge."],[0,"(b) Appointment of attorney by court"],[0,"Upon application by a person alleging a discriminatory housing practice or a person against whom such a practice is alleged, the court may—"],[1,"(1) appoint an attorney for such person; or"],[1,"(2) authorize the commencement or continuation of a civil action under subsection (a) without the payment of fees, costs, or security, if in the opinion of the court such person is financially unable to bear the costs of such action."],[0,"(c) Relief which may be granted"],[0,"(1) In a civil action under subsection (a), if the court finds that a discriminatory housing practice has occurred or is about to occur, the court may award to the plaintiff actual and punitive damages, and subject to subsection (d), may grant as relief, as the court deems appropriate, any permanent or temporary injunction, temporary restraining order, or other order (including an order enjoining the defendant from engaging in such practice or ordering such affirmative action as may be appropriate)."],[0,"(2) In a civil action under subsection (a), the court, in its discretion, may allow the prevailing party, other than the United States, a reasonable attorney's fee and costs. The United States shall be liable for such fees and costs to the same extent as a private person."],[0,"(d) Effect on certain sales, encumbrances, and rentals"],[0,"Relief granted under this section shall not affect any contract, sale, encumbrance, or lease consummated before the granting of such relief and involving a bona fide purchaser, encumbrancer, or tenant, without actual notice of the filing of a complaint with the Secretary or civil action under this subchapter."],[0,"(e) Intervention by Attorney General"],[0,"Upon timely application, the Attorney General may intervene in such civil action, if the Attorney General certifies that the case is of general public importance. Upon such intervention the Attorney General may obtain such relief as would be available to the Attorney General under section 3614(e) of this title in a civil action to which such section applies."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/3613?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3613. Enforcement by private persons","tname":"The Public Health and Welfare","by":{"1":"21","2":"6"}},{"t":"usc","label":"42 U.S.C. § 5311","url":"https://www.law.cornell.edu/uscode/text/42/5311","by":{"1":"26"}},{"t":"usc","label":"42 U.S.C. § 6869","url":"https://www.law.cornell.edu/uscode/text/42/6869","by":{"1":"26"}},{"t":"reg","label":"81 Fed. Reg. 28,974","url":"https://www.govinfo.gov/link/fr/81/28974","by":{"1":"5"}},{"t":"usc","label":"21 U.S.C. § 332","url":"https://www.law.cornell.edu/uscode/text/21/332","by":{"1":"18, 28"}},{"t":"usc","label":"21 U.S.C. § 333","url":"https://www.law.cornell.edu/uscode/text/21/333","by":{"1":"18, 28, 29"}},{"t":"usc","label":"21 U.S.C. § 334","url":"https://www.law.cornell.edu/uscode/text/21/334","by":{"1":"18, 28"}},{"t":"usc","label":"21 U.S.C. § 387","url":"https://www.law.cornell.edu/uscode/text/21/387","by":{"1":"34"}},{"t":"usc","label":"21 U.S.C. § 387k","url":"https://www.law.cornell.edu/uscode/text/21/387k","by":{"1":"28"}},{"t":"usc","label":"21 U.S.C. § 387r","url":"https://www.law.cornell.edu/uscode/text/21/387r","by":{"1":"5"}},{"t":"const","label":"Article III, Section 2","clauses":[["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"]],"text":"The judicial Power shall extend to all Cases, in Law and Equity, arising under this Constitution, the Laws of the United States, and Treaties made, or which shall be made, under their Authority;—to all Cases affecting Ambassadors, other public Ministers and Consuls;—to all Cases of admiralty and maritime Jurisdiction;—to Controversies to which the United States shall be a Party;—to Controversies between two or more States;— between a State and Citizens of another State,—between Citizens of different States,—between Citizens of the same State claiming Lands under Grants of different States, and between a State, or the Citizens thereof, and foreign States, Citizens or Subjects. In all Cases affecting Ambassadors, other public Ministers and Consuls, and those in which a State shall be Party, the supreme Court shall have original Jurisdiction. In all the other Cases before mentioned, the supreme Court shall have appellate Jurisdiction, both as to Law and Fact, with such Exceptions, and under such Regulations as the Congress shall make. The Trial of all Crimes, except in Cases of Impeachment, shall be by Jury; and such Trial shall be held in the State where the said Crimes shall have been committed; but when not committed within any State, the Trial shall be at such Place or Places as the Congress may by Law have directed.","by":{"1":"12"}},{"t":"case","label":"Abbott Laboratories v. Celebrezze","cite":"228 F. Supp. 855","y":1964,"court":"D. Del.","url":"https://www.courtlistener.com/c/F.%20Supp./228/855/","by":{"2":"17"}},{"t":"case","label":"Abbott Laboratories v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Allen v. Wright","cite":"468 U.S. 737","y":1984,"id":"1983/81-757","sc":1,"op":1,"sum":"The Court found that the circumstances involved in this case did not warrant federal-court adjudication.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"CBOCS West, Inc. v. Humphries","cite":"553 U.S. 442","y":2008,"id":"2007/06-1431","sc":1,"sum":"Section 1981 encompasses retaliation claims. The 7-2 decision, written by Justice Stephen Breyer, relied heavily on the concept of stare decisis, or adherence to prior Court decisions, in reaching its conclusion.","sumSrc":"Oyez","by":{"2":"19"}},{"t":"case","label":"Davis & Farnum Manufacturing Co. v. Los Angeles","cite":"189 U.S. 207","y":1903,"id":"scdb/1902-116","sc":1,"sum":"1. Where abill is based not only upon diversity of citizenship, but also upon the alleged uuconstitutionality of municipal ordinances as impairing the obligation of a contract, an appeal lies to this court and the whole case is opened for consideration.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"FBI v. Fikre","cite":"601 U.S. 234","y":2024,"id":"2023/22-1178","sc":1,"sum":"The Government failed to meet its burden to demonstrate that Mr. Fikre’s removal from the Government’s No Fly List mooted his 42 U. S. C. §1983 case because its declaration did not disclose the conduct that landed Mr. Fikre on the No Fly List and did not ensure that he would not be placed back on the list for engaging in the same or similar conduct in the future.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3"}},{"t":"case","label":"Hertz Corp. v. Friend","cite":"559 U.S. 77","y":2010,"id":"2009/08-1107","sc":1,"sum":"The Court held that the court system cannot disregard the location of a corporation's principal place of business in a multi-state lawsuit.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"INS v. Legalization Assistance Project","cite":"510 U.S. 1301","y":1993,"url":"https://supreme.justia.com/cases/federal/us/510/1301/","sc":1,"sum":"Concluding that an immigration statute protected only the interests of noncitizens, not those of employers, landlords, or non-profit organizations that were indirectly affected by immigration restrictions.","sumSrc":"brief:2","by":{"2":"7"}},{"t":"case","label":"Lesnik v. Public Industrials Corp.","cite":"144 F.2d 968","y":1944,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/144/968/","by":{"2":"13"}},{"t":"case","label":"Manchester Modes, Inc. v. Schuman","cite":"426 F.2d 629","y":1970,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/426/629/","by":{"2":"17"}},{"t":"case","label":"Marbury v. Madison","cite":"1 Cranch 137","y":1803,"url":"https://www.courtlistener.com/c/Cranch/1/137/","op":1,"by":{"2":"4"}},{"t":"case","label":"Mercantile National Bank v. Langdeau","cite":"371 U.S. 555","y":1963,"id":"1962/14_0","sc":1,"by":{"2":"3"}},{"t":"case","label":"Milner v. Department of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"op":7,"sum":"Observing that “absurd consequences” about who was entitled to sue would follow if the Court were to interpret literally a similarly worded cause of action.","sumSrc":"opinion","by":{"2":"19"}},{"t":"case","label":"Minor v. Mechanics Bank","cite":"1 Pet. 46","y":1828,"url":"https://www.courtlistener.com/c/Pet./1/46/","by":{"2":"2"}},{"t":"case","label":"Mississippi Publishing Corp. v. Murphree","cite":"326 U.S. 438","y":1946,"id":"scdb/1945-120","sc":1,"op":3,"sum":"Respondent, a resident of the northern district of Mississippi, brought suit in the federal district court for that district against petitioner, a Delaware corporation having an office and place of business in the southern district of Mississippi, to recover damages in an amount exceeding $3,000 for libel published in the southern district. The suit was begun by service of summons in the southern district by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Moody v. NetChoice, LLC","cite":"603 U.S. 707","y":2024,"id":"2023/22-277","sc":1,"sum":"The judgments are vacated, and the cases are remanded, because neither the Eleventh Circuit nor the Fifth Circuit conducted a proper analysis of the facial First Amendment challenges to the Florida and Texas laws regulating large internet platforms.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3"}},{"t":"case","label":"Morrison v. National Australia Bank Ltd.","cite":"561 U.S. 247","y":2010,"id":"2009/08-1191","sc":1,"sum":"The Court held that the Securities and Exchange Act does not provide a cause of action against foreign plaintiffs suing foreign and American defendants for misconduct in connection with securities traded on foreign stock exchanges.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Murthy v. Missouri","cite":"603 U.S. 43","y":2024,"id":"2023/23-411","sc":1,"sum":"Respondents—two States and five individual social-media users who sued Executive Branch officials and agencies, alleging that the Government pressured the platforms to censor their speech in violation of the First Amendment—lack Article III standing to seek an injunction.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3"}},{"t":"case","label":"Romero v. International Terminal Operating Co.","cite":"358 U.S. 354","y":1959,"id":"1958/3","sc":1,"sum":"The Supreme Court held that the district court confused jurisdiction with stating a valid cause of action. The district court had jurisdiction to determine whether Romero had stated a valid cause of action under the Jones Act and pendant jurisdiction joins the general maritime law claims. The Court also found that U.S. maritime law does not apply as a matter of law.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"Rubin v. Islamic Republic of Iran","cite":"583 U.S. 202","y":2018,"id":"2017/16-534","sc":1,"sum":"The Court held that 28 U.S.C. § 1610(g) does not provide a freestanding attachment immunity exception that allows terror victim judgment creditors to attach and execute upon assets of foreign state; rather, the immunity of property must be rescinded under a separate provision under that section.","sumSrc":"Oyez","by":{"2":"21"}},{"t":"case","label":"Schenley Distillers Corp. v. United States","cite":"326 U.S. 432","y":1946,"id":"scdb/1945-098","sc":1,"sum":"In order to obtain a determination as to whether it was a \"contract carrier by motor vehicle\" as defined by § 203 (a) (15) of Part II of the Interstate Commerce Act or a \"private carrier of property by motor vehicle\" as defined by § 203 (a) (17), one of the appellants applied to the Interstate Commerce Commission for a permit under § 209 (b) to operate as a \"contract carrier.\" In the proceedings before the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Trump v. United States","cite":"603 U.S. 593","y":2024,"id":"2023/23-939","sc":1,"sum":"The nature of Presidential power entitles a former President to absolute immunity from criminal prosecution for actions within his conclusive and preclusive constitutional authority; he is also entitled to at least presumptive immunity from prosecution for all his official acts; there is no immunity for unofficial acts.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"3"}},{"t":"case","label":"United States v. Williams","cite":"504 U.S. 36","y":1992,"id":"1991/90-1972","sc":1,"sum":"Respondent Williams was indicted by a federal grand jury for alleged violations of 18 U. S. C. § 1014. On his motion, the District Court ordered the indictment dismissed without prejudice because the Government had failed to fulfill its obligation under Circuit precedent to present \"substantial exculpatory evidence\" to the grand jury. Following that precedent, the Court of Appeals affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Walters v. National Ass’n of Radiation Survivors","cite":"473 U.S. 305","y":1985,"id":"1984/84-571","sc":1,"sum":"Title 38 U. S. C. § 3404(c) limits to $10 the fee that may be paid an attorney or agent who represents a veteran seeking benefits from the Veterans' Administration (VA) for service-connected death or disability. Appellees (two veterans' organizations, three individual veterans, and a veteran's widow) brought an action in Federal District Court claiming that the fee limitation denied them any realistic opportunity to …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"2"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"2, 4"}},{"t":"usc","label":"28 U.S.C. § 2341","url":"https://www.law.cornell.edu/uscode/text/28/2341","subs":["(2)"],"by":{"2":"15"}},{"t":"usc","label":"5 U.S.C. § 501","url":"https://www.law.cornell.edu/uscode/text/5/501","by":{"2":"5"}},{"t":"usc","label":"42 U.S.C. § 3601","url":"https://www.law.cornell.edu/uscode/text/42/3601","by":{"2":"6"}},{"t":"usc","label":"42 U.S.C. § 3602","url":"https://www.law.cornell.edu/uscode/text/42/3602","subs":["(i)"],"by":{"2":"6"}},{"t":"law","label":"Pub. L. No. 99-562","url":"https://www.govinfo.gov/link/statute/100/3158","by":{"2":"14"}},{"t":"usc","label":"15 U.S.C. § 717r","url":"https://www.law.cornell.edu/uscode/text/15/717r","subs":["(b)"],"by":{"2":"18"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","subs":["(a)"],"by":{"2":"3, 3"}}]};